INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA', 'kiswahili', 6, 'Tofautisha sauti d/nd, ch/sh, j/nj na g/ng katika silabi, maneno na vitanzandimi', ARRAY['KISW.G6.KUSIKI.T1_MATAMSHI_BORA.a', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.b', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.c']::text[], 'Hears, says and writes the right sound in syllables and words with d/nd, ch/sh, j/nj na g/ng (jaa and njaa, chati and shati), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 6, 'Elewa maana ya msamiati katika kifungu', ARRAY['KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Works out what a word means from the passage it is in, and picks the right word for a gap, and does not choose a look-alike word or a word from a nearby sentence, in 8 of 10 new items.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 6, 'Elewa ujumbe, matukio na wahusika wa hadithi', ARRAY['KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c']::text[], 'Answers who, where, what happened and what the main message is from a short story, and puts events in order, without using outside knowledge or a detail from the wrong place, in 8 of 10 new questions.', '["choose the answer","type a short answer","put in order"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU', 'kiswahili', 6, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.a', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA', 'kiswahili', 6, 'Tambua na tumia vivumishi vya sifa', ARRAY['KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.a', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.b', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.c']::text[], 'Gives the adjective of quality (-zuri, -kubwa, -refu, -dogo) in the form that agrees with the noun (wazuri, kikubwa, mirefu) and does not use a form from another class or the singular for many, in 8 of 10 new sentences.', '["choose the adjective","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA', 'kiswahili', 6, 'Tambua na tumia vivumishi viashiria', ARRAY['KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.a', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.b', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.c']::text[], 'Picks the demonstrative that follows the noun and agrees with its class and number (mtoto huyu, vitabu hivi, miti hii, mawe haya), and the far form (yule, kile, wale) for what is far, in 8 of 10 new sentences.', '["choose the demonstrative","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH', 'kiswahili', 6, 'Tambua na tumia vivumishi vimilikishi', ARRAY['KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.a', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.b', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.c']::text[], 'Gives the possessive that agrees with the thing owned (mwalimu wangu, kitabu changu, vitabu vyenu, jicho langu) and with the owner (-angu, -ako, -ake, -etu, -enu, -ao), in 8 of 10 new sentences.', '["choose the possessive","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO', 'kiswahili', 6, 'Chagua maamkuzi na maagano yanayofaa', ARRAY['KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.a', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.b', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.c']::text[], 'Picks the greeting or farewell that fits the time and the number of people (Hujambo and Hamjambo, Kwaheri and Kwa herini, Lala salama at night, Marahaba as the answer to Shikamoo), in 8 of 10 new situations. Using them in real talk (outcome c) stays with the teacher.', '["choose the word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA', 'kiswahili', 6, 'Tumia mpangilio wa maneno katika kamusi', ARRAY['KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.a', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.b']::text[], 'Puts words in dictionary (alphabetical) order, looking at the second and third letter when the first letters match, and finds the word that comes first or last, in 8 of 10 new lists.', '["choose the first word","choose the last word","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI', 'kiswahili', 6, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.a', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI', 'kiswahili', 6, 'Tambua na tumia vivumishi vya idadi', ARRAY['KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.a', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.b', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.c']::text[], 'Gives the number word with the prefix of its noun from one to five (wawili, vitatu, minne, matano, mtoto mmoja) and without a prefix from six (ng''ombe sita), in 8 of 10 new sentences.', '["choose the number word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI', 'kiswahili', 6, 'Tambua na tumia vivumishi viulizi', ARRAY['KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.a', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.b', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.c']::text[], 'Picks -ngapi (how many), -pi (which one) or gani (what kind) as the question needs, with the prefix of the noun (wangapi, vingapi, yupi, kipi, ipi), in 8 of 10 new questions.', '["choose the question word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_', 'kiswahili', 6, 'Tambua na tumia kivumishi kirejeshi amba-', ARRAY['KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.a', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.b', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.c']::text[], 'Gives amba- with the ending that agrees with the noun before it (mwalimu ambaye, watoto ambao, kitabu ambacho, miti ambayo) and does not leave amba- bare, in 8 of 10 new sentences.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA', 'kiswahili', 6, 'Tambua vitendawili na uvitegue', ARRAY['KISW.G6.KUSIKI.T3_MATAMSHI_BORA.a', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA.b']::text[], 'Picks the kitendawili (riddle) from a methali, a nahau and an ordinary sentence, and gives the answer to a known riddle, in 8 of 10 new items. Setting and guessing riddles aloud (outcome b) stays with the teacher.', '["choose the riddle","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 6, 'Tambua vipengele vya kusoma kwa ufasaha', ARRAY['KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.a', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.a']::text[], 'Names what a fluent reader does (clear sounds, a fitting speed, a fitting voice, a pause at the koma and the kikomo, a rising voice for a question, fitting gestures) and does not take speed or loudness for fluency, in 8 of 10 new items. Reading a passage aloud (outcomes b to e) is judged by a teacher listening.', '["choose the answer","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA', 'kiswahili', 6, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.b', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.c', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.d', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 6, 'Tambua mitindo ya maandishi ya tarakilishi', ARRAY['KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.a']::text[], 'Names the styles of computer writing (herufi nzito, mlazo, saizi) and the actions kuhifadhi and kuchapisha, and does not take herufi kubwa for herufi nzito, in 8 of 10 new items. Typing a short text (outcome b) is a practical task.', '["choose the style","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL', 'kiswahili', 6, 'Andika kifungu kwa tarakilishi ukitumia mitindo mbalimbali ya maandishi', ARRAY['KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.b']::text[], 'Types a short paragraph on the theme and uses the text styles for a purpose (bold for the title, italics for a foreign or special word, a larger size for the heading, underlining a key word), selecting the text first, and saves it, in 8 of 10 new items or tasks.', '["chagua mtindo ufaao","panga hatua","tambua kosa","kazi ya vitendo (mwalimu anaangalia)"]'::jsonb, '["procedure","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS', 'kiswahili', 6, 'Tambua na tumia viwakilishi vya nafsi', ARRAY['KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.a', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.b', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.c']::text[], 'Picks mimi, wewe, yeye, sisi, ninyi or wao by who speaks, who is spoken to and who is spoken about, and by one or many, in 8 of 10 new sentences.', '["choose the pronoun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI', 'kiswahili', 6, 'Tambua na tumia viwakilishi viashiria', ARRAY['KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.a', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.b', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.c']::text[], 'Uses a demonstrative that stands alone in place of the noun (Huyu ni rafiki yangu, Hivi ni vitabu), with the right class and number, and tells it from the demonstrative that follows a noun, in 8 of 10 new sentences.', '["choose the pronoun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD', 'kiswahili', 6, 'Tambua na tumia viwakilishi vya idadi', ARRAY['KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.a', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.b', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.c']::text[], 'Uses a number word on its own in place of the noun (Wawili walichelewa, Vitatu nilimpa Wanjiru) with the prefix of the noun left out of the sentence, in 8 of 10 new sentences.', '["choose the pronoun","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA', 'KISW.G6.SARUFI.T3_UAKIFISHI', 'kiswahili', 6, 'Tumia alama ya hisi, ritifaa na koloni', ARRAY['KISW.G6.SARUFI.T3_UAKIFISHI.a', 'KISW.G6.SARUFI.T3_UAKIFISHI.b']::text[], 'Chooses the sentence with the right alama ya hisi (!), ritifaa ('') as in ng''ombe, and koloni (:) before a list, in 8 of 10 new sentences.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE', 'kiswahili', 6, 'Tambua na tumia maneno ya heshima', ARRAY['KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.a', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.b']::text[], 'Picks the polite word the situation needs (tafadhali to ask, asante to thank, samahani to say sorry, pole to comfort, karibu to welcome, shikamoo to greet an elder) and the sentence that is polite, in 8 of 10 new items. Using the words in daily talk (outcome c) stays with the teacher.', '["choose the word","fill the gap","spot the mistake","choose the polite sentence"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 6, 'Zingatia hatua za kiusalama unapotumia vifaa vya kidijitali', ARRAY['KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.a', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses the safe step when reading on a phone, tablet or computer (use a site an adult or teacher suggested, keep the password secret, ask an adult before an unknown link, log out) and not the unsafe one, in 8 of 10 new situations. Searching and opening a file (outcomes b and c) is a practical task for the teacher.', '["choose the safe step","spot the unsafe step"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA', 'kiswahili', 6, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.b', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.c']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI', 'KISW.G6.KUANDI.T4_BARUA_RASMI', 'kiswahili', 6, 'Tambua muundo na vipengele vya barua rasmi', ARRAY['KISW.G6.KUANDI.T4_BARUA_RASMI.a', 'KISW.G6.KUANDI.T4_BARUA_RASMI.b']::text[], 'Names the parts of a barua rasmi (anwani ya mwandikaji kulia, tarehe, anwani ya mwandikiwa kushoto, salamu, kichwa, mwili, mwisho "Wako mwaminifu", sahihi na jina) and tells it from a friendly letter, in 8 of 10 new items. Writing the letter (outcome c) is composition marking.', '["choose the part","fill the gap","spot the mistake","choose the right wording"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'KISW.G6.KUANDI.T4_BARUA_RASMI', 'kiswahili', 6, 'Andika barua rasmi kwa muundo na lugha ifaayo', ARRAY['KISW.G6.KUANDI.T4_BARUA_RASMI.c']::text[], 'Tells barua rasmi from other kinds of writing and its parts, and writes an official letter with two addresses, the date, a formal greeting, a KUH: line, the message and Wako mtiifu with a signature; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA', 'kiswahili', 6, 'Tumia ngeli ya YA-YA kwa upatanisho wa kisarufi', ARRAY['KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.a', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.b', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.c']::text[], 'Knows nouns that belong to YA-YA (maji, maziwa, mafuta, mate, machozi, manukato; they begin with ma- and have no singular), gives ya- as the subject prefix, and does not use li- or a prefix of another class, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake","choose the noun"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS', 'kiswahili', 6, 'Tambua na eleza maana ya methali za umoja na ushirikiano', ARRAY['KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.a', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.b', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.c']::text[], 'Completes a methali about unity and working together (umoja ni nguvu, kidole kimoja hakivunji chawa, mkono mmoja haulei mwana, wengi wape) and says what it means, and does not read it word for word, in 8 of 10 new items. Using a methali when speaking (outcome c) stays with the teacher.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 6, 'Tambua aina za mashairi: tathnia, tathlitha, tarbia', ARRAY['KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c']::text[], 'Names the kind of poem by the lines in a stanza (tathnia: two, tathlitha: three, tarbia: four), and names the two parts of a line (ukwapi, the first, and utao, the second), without swapping them or counting mizani instead, in 8 of 10 new items. Reading a poem for its message (outcome c) stays with the teacher.', '["choose the kind","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO', 'kiswahili', 6, 'Tambua insha ya wasifu, masimulizi na maelezo', ARRAY['KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.a']::text[], 'Tells a short text that describes a person (wasifu), one that tells events in order (masimulizi) and one that explains how something is done or what it is (maelezo), in 8 of 10 new short texts.', '["choose the kind of text","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO', 'kiswahili', 6, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U', 'kiswahili', 6, 'Tumia ngeli ya U-U kwa upatanisho wa kisarufi', ARRAY['KISW.G6.SARUFI.T5_NGELI_YA_U_U.a', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.b', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.c']::text[], 'Knows nouns that belong to U-U (uji, unga, ugali, usingizi, uchafu, wino, mchele, mchanga: no plural), gives u- as the subject prefix, and does not use ya- or i-, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake","choose the noun"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA', 'kiswahili', 6, 'Kariri shairi kwa matamshi bora na ueleze msamiati na ujumbe wake', ARRAY['KISW.G6.KUSIKI.T6_MATAMSHI_BORA.a', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.b', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.c', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.d']::text[], 'Recites or sings a poem on gender equality with clear target sounds and its beat, explains a word of the poem from its line and uses it in a sentence, and answers questions on the message from the poem only, in 8 of 10 new items (the recitation scored by the teacher).', '["chagua maana ya neno","jibu swali la ujumbe","chagua ukariri bora","kariri (mwalimu anasikiliza)"]'::jsonb, '["recall","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA', 'kiswahili', 6, 'Chagua makala maktabani kwa vigezo na uyasome kupata ujumbe', ARRAY['KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.a', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.b', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.c']::text[], 'Chooses an article in the library by what to look for (topic, level, date, author), tells an article from a story or a poem, reads it and gives its message, telling the main point from its examples, in 8 of 10 new items.', '["chagua makala","chagua kigezo cha kuchagua","chagua ujumbe","tambua aina ya matini"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU', 'kiswahili', 6, 'Tambua sehemu za insha ya wasifu', ARRAY['KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.a']::text[], 'Names the parts of an insha (kichwa, utangulizi, mwili, hitimisho) and puts a sentence in the right part of a wasifu, in 8 of 10 new items. Writing the insha (outcomes b and c) is composition marking.', '["choose the part","fill the gap","spot the mistake","choose the sentence"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU', 'kiswahili', 6, 'Tambua na andika insha ya wasifu', ARRAY['KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I', 'kiswahili', 6, 'Tumia ngeli ya I-I kwa upatanisho wa kisarufi', ARRAY['KISW.G6.SARUFI.T6_NGELI_YA_I_I.a', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.b', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.c']::text[], 'Knows nouns that belong to I-I (afya, njaa, nguvu, subira, heshima, akili, haki, bahati: states and ideas that are not counted), gives i- as the subject prefix, and does not use zi- as for a plural, in 8 of 10 new items.', '["choose the prefix","fill the gap","spot the mistake","choose the noun"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T7_NAHAU.NAHAU', 'KISW.G6.KUSIKI.T7_NAHAU', 'kiswahili', 6, 'Tambua na eleza maana ya nahau za kazi na ushirikiano', ARRAY['KISW.G6.KUSIKI.T7_NAHAU.a', 'KISW.G6.KUSIKI.T7_NAHAU.b', 'KISW.G6.KUSIKI.T7_NAHAU.c']::text[], 'Completes a nahau about work and teamwork (kuchapa kazi, kuvaa njuga, kuunga mkono, kutoa jasho, kujikaza kisabuni, kufunga mkanda) and says what it means, and does not read it word for word, in 8 of 10 new items. Using a nahau when speaking (outcome c) stays with the teacher.', '["choose the meaning","fill the gap","spot the mistake"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA', 'kiswahili', 6, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.a', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.b', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.c']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO', 'kiswahili', 6, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.a', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU', 'kiswahili', 6, 'Tumia ngeli ya PA-KU-MU kwa upatanisho wa kisarufi', ARRAY['KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.a', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.b']::text[], 'Matches the word of place and the verb in PA-KU-MU: pa- for a particular place (pale pana), ku- for a far or general place (kule kuna), mu- or m- for inside (mle mna), in 8 of 10 new sentences.', '["choose the word","fill the gap","spot the mistake","choose the sentence"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T8_VISAWE.VISAWE', 'KISW.G6.KUSIKI.T8_VISAWE', 'kiswahili', 6, 'Tambua visawe na makundi ya maneno yenye maana sawa', ARRAY['KISW.G6.KUSIKI.T8_VISAWE.a', 'KISW.G6.KUSIKI.T8_VISAWE.b']::text[], 'Picks the word with almost the same meaning (furaha-bashasha, haraka-upesi) and the group of four words that all share one meaning, and does not pick the opposite, a related word or a group with one opposite in it, in 8 of 10 new items.', '["choose the word","fill the gap","spot the mistake","choose the group"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU', 'kiswahili', 6, 'Tambua na elewa mchezo wa kuigiza', ARRAY['KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.a', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.c', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.b']::text[], 'Tells a play from a story (names of speakers, words spoken, directions in brackets), says what a word in the play means, and answers questions about it, in 8 of 10 new items.', '["choose the answer","type a short answer","identify the part"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI', 'kiswahili', 6, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.a', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA', 'kiswahili', 6, 'Tambua na tumia kutendeana, kutendesha na kutendua', ARRAY['KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.a', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.b']::text[], 'Tells the three verb forms apart (kutendeana: each does it for the other, as in kuandikiana; kutendesha: makes someone do it, as in kuimbisha; kutendua: undoes it, as in kufungua) and picks the one a sentence needs, in 8 of 10 new items.', '["choose the verb","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT', 'kiswahili', 6, 'Tofautisha lugha rasmi na isiyo rasmi', ARRAY['KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.a', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.b']::text[], 'Tells formal language (for a meeting, a leader, a letter) from informal language (for friends and home) and picks the sentence that fits the person and the place, in 8 of 10 new items. Speaking in each context (outcome b, in full) stays with the teacher.', '["choose the kind","fill the gap","spot the mistake","choose the sentence"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA', 'kiswahili', 6, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.a', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.b']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO', 'kiswahili', 6, 'Tambua na andika insha ya maelezo', ARRAY['KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.a', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.b']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes an explanation or description on the topic, in order, with detail that makes a picture and no point off the topic; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH', 'kiswahili', 6, 'Tambua na tumia vinyume vya vivumishi', ARRAY['KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.a', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.b']::text[], 'Gives the true opposite of an adjective (mrefu-mfupi, mzito-mwepesi, mwerevu-mjinga) in the form that agrees with the noun, and does not repeat the word or pick a different adjective, in 8 of 10 new items.', '["choose the opposite","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA', 'kiswahili', 6, 'Tambua na tumia sitiari za tabia', ARRAY['KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.a', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.b', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.c']::text[], 'Completes a sitiari about behaviour (Kamau ni nyuki, mkuu wa shule ni simba, mwenzako ni kinyonga) and picks the sentence that is a sitiari and not a tashbihi (with kama) or a plain statement, in 8 of 10 new items. Using sitiari in speech (outcome c) stays with the teacher.', '["choose the word","fill the gap","spot the mistake","choose the sentence"]'::jsonb, '["recall","infer"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA', 'kiswahili', 6, 'Fungua faili, sakura kwenye tovuti salama na usome matini ya kidijitali', ARRAY['KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.a']::text[], 'Opens a saved file with the passage (finds the folder, double-clicks the file), searches a safe site with two or three key words, ignores pop-ups and adverts, and reads the passage for its message, in 8 of 10 new items or tasks.', '["chagua hatua sahihi","panga hatua","chagua maneno ya kutafutia","tambua kosa"]'::jsonb, '["procedure","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI', 'kiswahili', 6, 'Tambua na andika insha ya masimulizi', ARRAY['KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.a', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.b']::text[], 'Tells insha ya masimulizi from other kinds of writing and its parts, and writes a story of events in the past tense, in order, with a title, an opening, a middle and a closing that gives the lesson; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE', 'kiswahili', 6, 'Tambua na tumia hali ya masharti', ARRAY['KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.a', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.b']::text[], 'Uses -ki-, -sipo- and -nge- for a condition (Ukisoma, utafaulu; Usipomwagilia, itakauka; Ningekuwa tajiri, ningejenga) and does not use a tense marker (-li-, -na-, -ta-) in its place, in 8 of 10 new items.', '["choose the verb","fill the gap","spot the mistake","choose the marker"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH', 'kiswahili', 6, 'Sikiliza masimulizi kwa ujumbe na usimulie kwa ishara zifaazo', ARRAY['KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.a', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.b']::text[], 'Listens to a short narration and gives its message (not a detail), retells it in order, and tells his own story on the topic in Kiswahili sanifu with gestures that match the words; the teacher scores the telling with the KICD rubric, and in the app the child picks the message, order or gesture in 8 of 10 new items.', '["chagua ujumbe","panga matukio uliyosikia","chagua ishara ifaayo","kusimulia (mwalimu anasikiliza)"]'::jsonb, '["listening","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA', 'kiswahili', 6, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.b', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.c', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.d', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.e']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'KISW.G6.KUANDI.T11_BARUA_RASMI', 'kiswahili', 6, 'Andika barua rasmi kwa muundo na lugha ifaayo', ARRAY['KISW.G6.KUANDI.T11_BARUA_RASMI.a', 'KISW.G6.KUANDI.T11_BARUA_RASMI.b']::text[], 'Tells barua rasmi from other kinds of writing and its parts, and writes an official letter with two addresses, the date, a formal greeting, a KUH: line, the message and Wako mtiifu with a signature; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO', 'kiswahili', 6, 'Kanusha viambishi vya hali ya masharti', ARRAY['KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.a', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.b']::text[], 'Makes the negative of a verb with -ki- by changing -ki- to -sipo- (Ukisoma, Usiposoma) and does not only add si- or keep -ki-, in 8 of 10 new items.', '["choose the negative","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N', 'kiswahili', 6, 'Badilisha nomino za ki- kuwa ukubwa na udogo', ARRAY['KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.a', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.b', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.c']::text[], 'Gives the big form (ji-) and the small form (kiji-) of nouns that begin with ki- (kitabu: jitabu, kijitabu) and their plurals (majitabu, vijitabu), in 8 of 10 new items.', '["choose the form","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2', 'kiswahili', 6, 'Badilisha nomino za ji- kuwa ukubwa na udogo', ARRAY['KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.a', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.b', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.c']::text[], 'Recognises nouns that already begin with ji- (jiwe, jicho, jino), makes the big form by adding ji- again or with jiji-/ji- as the dictionary gives it (jiwe -> jijiwe) and the small form with kiji- (kijiwe), and agrees each with LI-YA or KI-VI, in 8 of 10 new items.', '["badilisha nomino","jaza pengo","tambua kosa la upatanisho"]'::jsonb, '["rule","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'skill', 'essential', 'Grade 5 told f/v, s/z, l/r and th/dh apart: the same listening for one feature.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'KISW.G5.KUSIKI.T1_MATAMSHI_BORA_SAUTI_.c', 'outcome', 'helpful', 'Saying tongue twisters on close sounds was practised in Grade 5.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'KISW.G5.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'skill', 'essential', 'Grade 5 explained word meanings from the passage.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a native Kiswahili teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
