INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M6_MAT_SWAP_T1', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Hears or says /nj/ for /j/, so jaa (to be full) becomes njaa (hunger).', '{"question":"Mwalimu anasema: \"jaa\". Umesikia neno lipi?","wrong_answer":"njaa","correct_answer":"jaa"}'::jsonb, 'The nasal (n- or m-) before j is soft and quick; a child who does not hear it writes and says the word without it, or adds it where it does not belong, and the meaning changes.', 'The question "Mwalimu anasema: "jaa". Umesikia neno lipi?" with "njaa" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M6_MAT_SPELL_T1', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Writes the word with the letter of the other sound (shati where chati is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"a chart\".","wrong_answer":"shati","correct_answer":"chati"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "a chart"." with "shati" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M6_MAT_SAME_T1', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"chati\" na \"shati\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""chati" na "shati" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M6_MAT_TWISTER_T1', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Moyo husukuma damu mwilini kila wakati.","correct_answer":"Njaa ya Njeri ilijaa njiani, akanywa chai na kula ndizi ndani ya nyumba ndogo."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Moyo husukuma damu mwilini kila wakati." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI.M6_MAT_SYLL_T1', 'KISW.G6.KUSIKI.T1_MATAMSHI_BORA.MATAMSHI', 'Splits the syllable with the nasal wrongly (n-jaa instead of keeping the nasal with its consonant).', '{"question":"Neno \"njaa\" lina silabi zipi?","wrong_answer":"n-jaa","correct_answer":"nja-a"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "njaa" lina silabi zipi?" with "n-jaa" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_LOOKALIKE', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word that looks or sounds like the word in the passage.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kuchemka kwa maji","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child reads the first letters and not the meaning.', 'A word with a look-alike among the options.', 'Read the sentence around the word and think what is being done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_NEARBY', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks a word from a nearby sentence that is not about this word.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kuchuma majani ya chai","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child grabs the first thing the passage says.', 'An option taken from another sentence.', 'Go back to the exact sentence with the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M_MSA_OPPOSITE', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Picks the opposite of the word.', '{"question":"Katika kifungu, \"kuchemsha\" maana yake ni nini?","wrong_answer":"kupoza maji","correct_answer":"kupasha maji moto hadi yatokote"}'::jsonb, 'The child finds the idea and then reverses it.', 'An option with the opposite meaning.', 'Does the word mean the same thing as your choice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_WRONG_PERSON', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives another character for who did it.', '{"question":"Nani alimsaidia Wanjiru?","wrong_answer":"mwalimu","correct_answer":"bibi yake"}'::jsonb, 'The child remembers several names and joins them.', 'A who-question with another character as an option.', 'Find the sentence with the action and see who did it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_OUTSIDE', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Answers from what the child knows, not from what the passage says.', '{"question":"Walipika chakula gani?","wrong_answer":"ugali","correct_answer":"mchele"}'::jsonb, 'The child answers a Kenyan child''s common meal rather than the one in the passage.', 'A question whose answer is not the usual one.', 'Underline the answer in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_DETAIL_AS_MAIN', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives a small detail as the main message.', '{"question":"Ujumbe mkuu wa hadithi ni upi?","wrong_answer":"Wanjiru alikuwa na sufuria nyekundu.","correct_answer":"Kusaidiana kunafanya kazi iwe rahisi."}'::jsonb, 'The child chooses a sentence that is easy to find.', 'A main-message question with a detail as one option.', 'Ask "Hadithi nzima inatufundisha nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_ORDER', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Puts events in the order they are told in the question, not in the story.', '{"question":"Panga matukio kwa mpangilio.","wrong_answer":"D, A, C, B","correct_answer":"A, B, C, D"}'::jsonb, 'The child does not go back to the story.', 'Ordering four events from the story.', 'Find each event in the story and see which came first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI.M_UFA_DETAIL_MIX', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.UFAHAMU_HADITHI', 'Gives a detail from the passage that belongs to another part of the story.', '{"question":"Wanjiru alichemsha maji katika nini?","wrong_answer":"kikombe","correct_answer":"sufuria kubwa"}'::jsonb, 'The child remembers many details and joins the wrong ones.', 'A what-or-where question with another detail of the passage as an option.', 'Find the exact sentence with the action in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI.M6_MSA_BODY_GENERAL', 'KISW.G6.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.MSAMIATI', 'Explains an organ word with a general word (figo = sehemu ya mwili) that does not tell it from other organs.', '{"question":"Katika kifungu, \"figo\" ni nini?","wrong_answer":"sehemu ya mwili","correct_answer":"kiungo cha ndani kinachochuja damu na kutoa mkojo"}'::jsonb, 'The child gives the category, which feels like a definition.', 'The question "Katika kifungu, "figo" ni nini?" with "sehemu ya mwili" among the options.', 'Ask: which part, and what does it do? A definition names the job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_STORY_T1', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Moyo: Kiungo Muhimu Mwilini\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Moyo ni kiungo chenye umbo la ngumi, kilicho upande wa kushoto wa kifua."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Moyo: Kiungo Muhimu Mwilini"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_DETAIL_T1', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Moyo: Kiungo Muhimu Mwilini\"?","wrong_answer":"Moyo ni muhimu sana.","correct_answer":"Moyo ni kiungo chenye umbo la ngumi, kilicho upande wa kushoto wa kifua."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Moyo: Kiungo Muhimu Mwilini"?" with "Moyo ni muhimu sana." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_AGREE_T1', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Moyo ni kiungo mdogo lakini chenye nguvu.","correct_answer":"Moyo ni kiungo kidogo lakini chenye nguvu."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Moyo ni kiungo mdogo lakini chenye nguvu." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_OFFTOPIC_T1', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Moyo: Kiungo Muhimu Mwilini\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Moyo ni kiungo chenye umbo la ngumi, kilicho upande wa kushoto wa kifua."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Moyo: Kiungo Muhimu Mwilini", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_PARAS_T1', 'KISW.G6.KUANDI.T1_INSHA_YA_WASIFU.INSHA_WASIFU', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Moyo: Kiungo Muhimu Mwilini\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Moyo: Kiungo Muhimu Mwilini" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA.M_SIFA_NUMBER', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA', 'Uses the singular adjective with a plural noun, or the plural with a singular noun (wanafunzi mzuri).', '{"question":"Wanafunzi ___ walipata zawadi.","wrong_answer":"mzuri","correct_answer":"wazuri"}'::jsonb, 'English adjectives do not change with number, so the child keeps one form.', 'The question "Wanafunzi ___ walipata zawadi." with "mzuri" among the options.', 'Ask "Wanafunzi ni mmoja au wengi? Kivumishi kinaonyesha nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA.M_SIFA_NO_AGREE', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA', 'Uses an adjective with the prefix of another noun class (kitabu mkubwa).', '{"question":"Kitabu ___ kiko mezani.","wrong_answer":"mkubwa","correct_answer":"kikubwa"}'::jsonb, 'The child learned one prefix and uses it for every noun.', 'The question "Kitabu ___ kiko mezani." with "mkubwa" among the options.', 'A gap with a noun of KI-VI and options from other classes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA.M_SIFA_NOT_ADJ', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA', 'Picks a noun (ukarimu) where an adjective (mkarimu) is needed.', '{"question":"Mkulima ___ alipanda mahindi mengi.","wrong_answer":"ukarimu","correct_answer":"mkarimu"}'::jsonb, 'The child does not yet tell an adjective from the noun made from it.', 'The question "Mkulima ___ alipanda mahindi mengi." with "ukarimu" among the options.', 'Options that include the noun and the adjective of the same word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA.M6_SIFA_ORDER', 'KISW.G6.SARUFI.T1_VIVUMISHI_VYA_SIFA.SIFA', 'Puts the adjective before the noun, English style (mrefu mti, mzuri msichana).', '{"question":"Ni ipi ni sahihi?","wrong_answer":"mrefu mti","correct_answer":"mti mrefu"}'::jsonb, 'The English order (a tall tree) carries over.', 'The question "Ni ipi ni sahihi?" with "mrefu mti" among the options.', 'Build noun + adjective phrases with cards that must sit in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA.M_VIASH_NUMBER', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA', 'Uses the singular demonstrative with a plural noun (watoto huyu).', '{"question":"Vitabu ___ ni vya maktaba.","wrong_answer":"hiki","correct_answer":"hivi"}'::jsonb, 'The child matches the class but not the number.', 'The question "Vitabu ___ ni vya maktaba." with "hiki" among the options.', 'A plural noun with the singular form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA.M_VIASH_CLASS', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA', 'Uses a demonstrative of another noun class (mti hii, nyumba huu).', '{"question":"Mawe ___ ni mazito.","wrong_answer":"hivi","correct_answer":"haya"}'::jsonb, 'The child has learned the demonstrative of one class by heart and uses it everywhere.', 'The question "Mawe ___ ni mazito." with "hivi" among the options.', 'A gap with several classes among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA.M_VIASH_FAR', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA', 'Uses the near demonstrative (huyu, hiki) for something far (yule, kile).', '{"question":"Mtoto ___ aliye mbali na sisi ni mdogo wangu.","wrong_answer":"huyu","correct_answer":"yule"}'::jsonb, 'The child does not read the clue about distance in the sentence.', 'The question "Mtoto ___ aliye mbali na sisi ni mdogo wangu." with "huyu" among the options.', 'A sentence with a clue word such as mbali or kule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA.M6_VIASH_BEFORE', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIASHIRIA.VIASHIRIA', 'Puts the demonstrative before the noun in the ordinary order (hiki kitabu as the only form) and thinks kitabu hiki is wrong.', '{"question":"Ni ipi ni ya kawaida katika Kiswahili?","wrong_answer":"hiki kitabu tu","correct_answer":"kitabu hiki (na hiki kitabu kwa msisitizo)"}'::jsonb, 'English "this book" puts this first.', 'The question "Ni ipi ni ya kawaida katika Kiswahili?" with "hiki kitabu tu" among the options.', 'Show both orders; the usual one has the demonstrative after the noun; before it adds stress.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI.M_VIMIL_CLASS', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI', 'Uses the possessive of another noun class (kitabu yangu, mwalimu changu).', '{"question":"Kitabu ___ kimepotea.","wrong_answer":"wangu","correct_answer":"changu"}'::jsonb, 'The child uses the possessive that goes with people for every noun.', 'The question "Kitabu ___ kimepotea." with "wangu" among the options.', 'A gap with a thing noun and options from other classes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI.M_VIMIL_NUMBER', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI', 'Uses the singular possessive with a plural noun (vitabu changu).', '{"question":"Vitabu ___ viko mezani.","wrong_answer":"chenu","correct_answer":"vyenu"}'::jsonb, 'The child matches the class but forgets the number.', 'The question "Vitabu ___ viko mezani." with "chenu" among the options.', 'A plural noun with the singular form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI.M_VIMIL_PERSON', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI', 'Uses the possessive of the wrong owner (shule yangu where the owners are we).', '{"question":"Sisi tunapenda shule ___.","wrong_answer":"yangu","correct_answer":"yetu"}'::jsonb, 'The child does not match the owner (-angu, -ako, -ake, -etu, -enu, -ao).', 'The question "Sisi tunapenda shule ___." with "yangu" among the options.', 'A sentence about we or they with -angu among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI.M6_VIMIL_WA_ONLY', 'KISW.G6.SARUFI.T1_VIVUMISHI_VIMILIKISH.VIMILIKISHI', 'Uses wa- (wangu) for every noun because it is the form used for people (kitabu wangu).', '{"question":"Jaza: Kitabu ___ ni kipya.","wrong_answer":"wangu","correct_answer":"changu"}'::jsonb, 'Wangu is the first possessive learnt (mama wangu) and it spreads.', 'The question "Jaza: Kitabu ___ ni kipya." with "wangu" among the options.', 'Make a table by class: wangu, changu, langu, yangu, zangu, wangu (mti).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M_MAA_NUMBER', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses the greeting or farewell for one person with many (Hujambo for Hamjambo, Kwaheri for Kwa herini).', '{"question":"Unawasalimia wanafunzi wengi darasani: \"___!\"","wrong_answer":"Hujambo","correct_answer":"Hamjambo"}'::jsonb, 'The child learned the greeting for one person and uses it for everyone.', 'The question "Unawasalimia wanafunzi wengi darasani: "___!"" with "Hujambo" among the options.', 'A situation with many people and both greetings among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M_MAA_TIME', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a night farewell in the morning or a morning greeting at night.', '{"question":"Asubuhi unamwamkia mwalimu: \"___, mwalimu.\"","wrong_answer":"Lala salama","correct_answer":"Habari za asubuhi"}'::jsonb, 'The child does not match the greeting to the time of day.', 'The question "Asubuhi unamwamkia mwalimu: "___, mwalimu."" with "Lala salama" among the options.', 'A situation with a clue word such as asubuhi or usiku.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M_MAA_FAREWELL', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting where a farewell is needed, or a farewell where a greeting is needed (Hujambo when leaving).', '{"question":"Unaondoka na kumwaga mtu mmoja: \"___!\"","wrong_answer":"Hujambo","correct_answer":"Kwaheri"}'::jsonb, 'The child does not ask whether he is arriving or leaving.', 'The question "Unaondoka na kumwaga mtu mmoja: "___!"" with "Hujambo" among the options.', 'A leaving situation with a greeting among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M_MAA_REPLY', 'KISW.G6.KUSIKI.T2_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Repeats the greeting (Shikamoo) where the reply (Marahaba) is needed.', '{"question":"Mdogo anamwambia mzee \"Shikamoo\". Mzee anajibu: \"___.\"","wrong_answer":"Shikamoo","correct_answer":"Marahaba"}'::jsonb, 'The child does not know the reply is a different word.', 'The question "Mdogo anamwambia mzee "Shikamoo". Mzee anajibu: "___."" with "Shikamoo" among the options.', 'The elder''s turn with both words among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_LENGTH', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Puts words in order of length, not alphabet.', '{"question":"Neno gani huja kwanza kwenye kamusi?","wrong_answer":"mti","correct_answer":"baba"}'::jsonb, 'The child looks for the shortest or the first-looking word.', 'Words of different lengths.', 'Say the alphabet and look at the first letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_FIRST_ONLY', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Looks only at the first letter and picks any word with the same first letter.', '{"question":"Neno gani huja kwanza kwenye kamusi?","wrong_answer":"samaki","correct_answer":"sahani"}'::jsonb, 'The child stops at the first letter when two words begin the same.', 'Words that begin with the same letter.', 'When the first letters match, look at the second letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M_KAM_REVERSE', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Puts the end of the alphabet first.', '{"question":"Neno gani huja mwisho kwenye kamusi?","wrong_answer":"ndizi","correct_answer":"zeze"}'::jsonb, 'The child mixes first and last.', 'A question that asks for the last word.', 'A comes first and Z comes last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI.M6_KAM_INFO', 'KISW.G6.KUSOMA.T2_KUSOMA_KWA_KINA.KAMUSI', 'Reads only the meaning and ignores the other information the dictionary gives (ngeli, aina ya neno, wingi).', '{"question":"Kamusi inaandika: \"kiatu nm (ki-vi) vi-\". Herufi \"nm\" zinaonyesha nini?","wrong_answer":"maana ya neno","correct_answer":"aina ya neno: nomino"}'::jsonb, 'Nobody has shown the child the short forms in an entry.', 'The question "Kamusi inaandika: "kiatu nm (ki-vi) vi-". Herufi "nm" zinaonyesha nini?" with "maana ya neno" among the options.', 'Read one entry together and label each part: tahajia, aina, ngeli, wingi, maana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_FACTS_T2', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Mechi Isiyosahaulika\"?","wrong_answer":"Mpira wa miguu ni mchezo unaopendwa duniani.","correct_answer":"Timu yetu ilifunga bao dakika ya mwisho."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Mechi Isiyosahaulika"?" with "Mpira wa miguu ni mchezo unaopendwa duniani." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_TENSE_T2', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Mechi Isiyosahaulika\"?","wrong_answer":"Timu yetu inafunga bao dakika ya mwisho.","correct_answer":"Timu yetu ilifunga bao dakika ya mwisho."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Mechi Isiyosahaulika"?" with "Timu yetu inafunga bao dakika ya mwisho." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_ORDER_T2', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Mechi Isiyosahaulika\"?","wrong_answer":"tulisherehekea, tulifunga bao, mechi ilianza, tulifika uwanjani","correct_answer":"tulifika uwanjani, mechi ilianza, tulifunga bao, tulisherehekea"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Mechi Isiyosahaulika"?" with "tulisherehekea, tulifunga bao, mechi ilianza, tulifika uwanjani" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_END_T2', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Mechi Isiyosahaulika\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Mechi Isiyosahaulika"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_VIDOKEZO_T2', 'KISW.G6.KUANDI.T2_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Plans with points (vidokezo) that do not belong to the title, or writes the insha without using the points planned.', '{"question":"Ni kidokezo kipi hakifai kwa insha \"Mechi Isiyosahaulika\"?","wrong_answer":"Bei ya sukari imepanda dukani.","correct_answer":"tulifika uwanjani"}'::jsonb, 'The child lists whatever comes to mind and does not check each point against the title.', 'The question "Ni kidokezo kipi hakifai kwa insha "Mechi Isiyosahaulika"?" with "Bei ya sukari imepanda dukani." among the options.', 'Write the title at the top of the plan; tick each point only if it helps to tell that story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI.M_IDADI_CLASS', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI', 'Puts the prefix of another noun class on the number (vitabu watatu, wanafunzi viwili).', '{"question":"Vitabu ___ viko mezani.","wrong_answer":"watatu","correct_answer":"vitatu"}'::jsonb, 'The child knows the number words but not that they take the prefix of the noun.', 'The question "Vitabu ___ viko mezani." with "watatu" among the options.', 'A gap with a thing noun and the people form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI.M_IDADI_NO_PREFIX', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI', 'Writes the bare number (tatu, nne) without the prefix.', '{"question":"Miti ___ imekatwa.","wrong_answer":"nne","correct_answer":"minne"}'::jsonb, 'In English the number never changes.', 'The question "Miti ___ imekatwa." with "nne" among the options.', 'Options with the bare number word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI.M_IDADI_SIX_PLUS', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI', 'Adds a class prefix to numbers from six (ng''ombe wasita).', '{"question":"Baba ana ng''ombe ___.","wrong_answer":"wasita","correct_answer":"sita"}'::jsonb, 'The child over-applies the rule for one to five.', 'The question "Baba ana ng''ombe ___." with "wasita" among the options.', 'A sentence with sita, saba or nane.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI.M6_IDADI_ORDINAL', 'KISW.G6.SARUFI.T2_VIVUMISHI_VYA_IDADI.IDADI', 'Uses the counting number (watatu) where the position is meant (wa tatu), or the reverse.', '{"question":"Alishinda nafasi ipi katika mbio?","wrong_answer":"watatu","correct_answer":"ya tatu"}'::jsonb, 'Both use the same number word; the child does not hear the -a of position.', 'The question "Alishinda nafasi ipi katika mbio?" with "watatu" among the options.', 'Line up three runners: count them (watatu), then name the position (wa tatu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI.M_VIUL_CLASS', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI', 'Uses the question word of another noun class (vitabu wangapi).', '{"question":"Vitabu ___ vimepotea?","wrong_answer":"wangapi","correct_answer":"vingapi"}'::jsonb, 'The child uses the form for people for every noun.', 'The question "Vitabu ___ vimepotea?" with "wangapi" among the options.', 'A question about things with the people form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI.M_VIUL_NUMBER', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI', 'Uses the plural question word with one noun, or the singular with many (kitabu vipi).', '{"question":"Kitabu ___ ni chako?","wrong_answer":"vipi","correct_answer":"kipi"}'::jsonb, 'The child matches the class but not the number.', 'The question "Kitabu ___ ni chako?" with "vipi" among the options.', 'A question with one noun and the plural form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI.M_VIUL_KIND', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI', 'Confuses -ngapi (how many) with gani (what kind), or the other way.', '{"question":"Ulikula chakula ___ jana?","wrong_answer":"wangapi","correct_answer":"gani"}'::jsonb, 'The child does not ask what the question wants to know: a number, one of many, or a kind.', 'The question "Ulikula chakula ___ jana?" with "wangapi" among the options.', 'A question about kind with -ngapi among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI.M6_VIUL_NO_QMARK', 'KISW.G6.SARUFI.T2_VIVUMISHI_VIULIZI.VIULIZI', 'Writes a sentence with a question word and ends it with a full stop.', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Mlifunga mabao mangapi.","correct_answer":"Mlifunga mabao mangapi?"}'::jsonb, 'The child focuses on the question word and forgets the end mark.', 'The question "Ni ipi imeandikwa sawa?" with "Mlifunga mabao mangapi." among the options.', 'Underline the question word; circle the end mark; they go together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA.M_AMBA_CLASS', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA', 'Uses amba- with the ending of another noun class (kitabu ambaye).', '{"question":"Kitabu ___ nilinunua ni kizuri.","wrong_answer":"ambaye","correct_answer":"ambacho"}'::jsonb, 'The child uses ambaye for every noun.', 'The question "Kitabu ___ nilinunua ni kizuri." with "ambaye" among the options.', 'A thing noun with ambaye among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA.M_AMBA_NUMBER', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA', 'Uses the singular amba- form for many, or the plural for one (watoto ambaye).', '{"question":"Watoto ___ wanasoma ni werevu.","wrong_answer":"ambaye","correct_answer":"ambao"}'::jsonb, 'The child matches the class but not the number.', 'The question "Watoto ___ wanasoma ni werevu." with "ambaye" among the options.', 'A plural noun with the singular form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA.M_AMBA_NO_END', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA', 'Leaves amba- without its ending (mama amba anauza).', '{"question":"Mama ___ anauza mboga ni shangazi yangu.","wrong_answer":"amba","correct_answer":"ambaye"}'::jsonb, 'The child knows the stem but not that it needs an ending.', 'The question "Mama ___ anauza mboga ni shangazi yangu." with "amba" among the options.', 'Options with the bare stem amba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA.M6_AMBA_DOUBLE', 'KISW.G6.SARUFI.T2_KIVUMISHI_KIREJESHI_.AMBA', 'Uses amba- and the relative -ye- / -o- in the verb together (mtoto ambaye aliyekuja).', '{"question":"Ni ipi ni sahihi?","wrong_answer":"Mtoto ambaye aliyeshinda amepewa zawadi.","correct_answer":"Mtoto ambaye alishinda amepewa zawadi."}'::jsonb, 'Both ways of saying "who" are known and the child uses both to be sure.', 'The question "Ni ipi ni sahihi?" with "Mtoto ambaye aliyeshinda amepewa zawadi." among the options.', 'Show the two ways side by side: ambaye alishinda = aliyeshinda; never both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI.M_VIT_METHALI', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI', 'Takes a methali for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Haba na haba hujaza kibaba","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'Both are short sayings.', 'A riddle and a methali.', 'A riddle asks a hidden question and waits for the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI.M_VIT_NAHAU', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI', 'Takes a nahau for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Kukata tamaa","correct_answer":"Popote niendapo hunifuata"}'::jsonb, 'Both can be a short phrase.', 'A riddle and a nahau.', 'Can you guess an answer to it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI.M_VIT_PLAIN', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI', 'Takes an ordinary sentence for a riddle.', '{"question":"Ni kitendawili kipi?","wrong_answer":"Yai ni chakula kizuri","correct_answer":"Nyumba yangu haina mlango"}'::jsonb, 'The child does not see that a riddle hides the thing it describes.', 'A riddle and a plain sentence.', 'Does the text name the thing, or hide it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI.M_VIT_WRONG_ANSWER', 'KISW.G6.KUSIKI.T3_MATAMSHI_BORA.VITENDAWILI', 'Gives a thing that shares one detail with the riddle but is not the answer.', '{"question":"\"Popote niendapo hunifuata.\" Jibu ni nini?","wrong_answer":"mbwa","correct_answer":"kivuli"}'::jsonb, 'The child picks the first thing that comes to mind.', 'A riddle with plausible answers.', 'Test each answer against every part of the riddle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_SPEED', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Takes fast reading for fluent reading, or very slow reading for careful reading.', '{"question":"Kasi ifaayo ya kusoma ni ipi?","wrong_answer":"Haraka iwezekanavyo","correct_answer":"Si haraka sana wala polepole sana"}'::jsonb, 'The child thinks the best reader is the fastest.', 'A question on speed with extremes as options.', 'Ask whether the listener can follow every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_LOUD', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Takes a loud voice for a fitting voice.', '{"question":"Sauti ipasavyo wakati wa kusoma ni ipi?","wrong_answer":"Kupiga kelele","correct_answer":"Sauti inayosikika wazi bila kupiga kelele"}'::jsonb, 'The child thinks louder is better.', 'A question on the voice with shouting and whispering as options.', 'Ask whether the voice is clear and comfortable to listen to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M_UFS_IGNORE_MARKS', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Reads on without a pause at the koma and the kikomo.', '{"question":"Ukifika kwenye koma wakati wa kusoma, ufanye nini?","wrong_answer":"Niendelee bila kupumzika","correct_answer":"Nipumzike kidogo"}'::jsonb, 'The child reads word after word and does not use the marks.', 'A question on the pause at a koma or a kikomo.', 'Read the sentence aloud and listen to where the voice rests.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_WORDBYWORD_T3', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Ndugu wawili walipatana na kuishi kwa amani tena.\"?","wrong_answer":"Ndugu ... wawili ... walipatana ... na ... kuishi ... kwa ... amani ... tena.","correct_answer":"Ndugu wawili walipatana na kuishi kwa amani tena."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Ndugu wawili walipatana na kuishi kwa amani tena."?" with "Ndugu ... wawili ... walipatana ... na ... kuishi ... kwa ... amani ... tena." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_RACE_T3', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_FLAT_T3', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, umewahi kumsamehe rafiki aliyekukosea?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, umewahi kumsamehe rafiki aliyekukosea?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_NOPAUSE_T3', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Ala, kumbe ninyi ni ndugu!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Ala, kumbe ninyi ni ndugu!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_SOUND_T3', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (urafiki read as ulafiki).', '{"question":"Neno \"urafiki\" linatamkwa vipi?","wrong_answer":"ulafiki","correct_answer":"urafiki"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "urafiki" linatamkwa vipi?" with "ulafiki" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE.M6_UFS_FEELING', 'KISW.G6.KUSOMA.T3_KUSOMA_KWA_UFASAHA.UFASAHA_VIPENGELE', 'Thinks the voice should stay the same through a happy and a sad part.', '{"question":"Unasoma sehemu ya huzuni katika hadithi. Sauti yako iweje?","wrong_answer":"sawa na sehemu ya furaha","correct_answer":"ya chini na polepole kuonyesha huzuni"}'::jsonb, 'Fluent reading has been taught as accuracy and pace, not feeling.', 'The question "Unasoma sehemu ya huzuni katika hadithi. Sauti yako iweje?" with "sawa na sehemu ya furaha" among the options.', 'Read one happy and one sad line; the class names the feeling heard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI.M_TAR6_MIX', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI', 'Mixes herufi nzito, mlazo, saizi and rangi.', '{"question":"Herufi zinazoegemea upande huitwa herufi ___.","wrong_answer":"nzito","correct_answer":"mlazo"}'::jsonb, 'The child has used the buttons but does not know their names.', 'The question "Herufi zinazoegemea upande huitwa herufi ___." with "nzito" among the options.', 'Style names among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI.M_TAR6_CAPS', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI', 'Takes herufi kubwa or ndogo (capital or small letters) for a style such as herufi nzito.', '{"question":"Herufi zilizonenepeshwa huitwa herufi ___.","wrong_answer":"kubwa","correct_answer":"nzito"}'::jsonb, 'The child thinks big and bold are the same.', 'The question "Herufi zilizonenepeshwa huitwa herufi ___." with "kubwa" among the options.', 'Kubwa among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI.M_TAR6_ICON', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI', 'Mixes the actions kuhifadhi (save), kuchapisha (print), kufuta (delete) and kufunga (close).', '{"question":"Kuweka kazi yako salama katika tarakilishi huitwa ___.","wrong_answer":"kuchapisha","correct_answer":"kuhifadhi"}'::jsonb, 'The child does not know what each button does.', 'The question "Kuweka kazi yako salama katika tarakilishi huitwa ___." with "kuchapisha" among the options.', 'Several actions among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO.M6_CHM_ALL_BOLD', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO', 'Makes the whole paragraph bold or large so it "looks important", so the title no longer stands out.', '{"question":"Ni kipi kinafaa kuwa na herufi nzito katika kifungu chako?","wrong_answer":"kifungu chote","correct_answer":"anwani tu"}'::jsonb, 'The child thinks styles make writing better in general.', 'The question "Ni kipi kinafaa kuwa na herufi nzito katika kifungu chako?" with "kifungu chote" among the options.', 'Show a page with everything bold beside one with only the title bold; which title stands out?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO.M6_CHM_NO_SELECT', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO', 'Clicks a style button without selecting the text first and expects the text above to change.', '{"question":"Unataka neno \"urafiki\" liwe la mlazo. Unaanza na nini?","wrong_answer":"bonyeza I","correct_answer":"chagua neno \"urafiki\", kisha bonyeza I"}'::jsonb, 'The order (select, then act) is not yet a habit.', 'The question "Unataka neno "urafiki" liwe la mlazo. Unaanza na nini?" with "bonyeza I" among the options.', 'Say aloud: "chagua, kisha bonyeza" each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO.M6_CHM_WRONG_STYLE', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO', 'Uses underlining or colour where the purpose needs italics (a book title, a word from another language).', '{"question":"Jina la kitabu \"Kisima cha Giningi\" katika kifungu liandikwe vipi?","wrong_answer":"kwa rangi nyekundu","correct_answer":"kwa herufi za mlazo"}'::jsonb, 'All styles look like decoration to the child.', 'The question "Jina la kitabu "Kisima cha Giningi" katika kifungu liandikwe vipi?" with "kwa rangi nyekundu" among the options.', 'Make a purpose chart: anwani - nzito; jina la kitabu - mlazo; neno muhimu - kupigiwa mstari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO.M6_CHM_UNSAVED_CHANGES', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.CHAPA_MITINDO', 'Closes after styling without saving the changes, or saves under a new name each time (Kazi1, Kazi2, Kazi3).', '{"question":"Umebadilisha mitindo ya kifungu ulichohifadhi jana. Ufanye nini kabla ya kufunga?","wrong_answer":"funga tu","correct_answer":"hifadhi tena kwa jina lilelile"}'::jsonb, 'The child does not know the saved copy is the old one until saved again.', 'The question "Umebadilisha mitindo ya kifungu ulichohifadhi jana. Ufanye nini kabla ya kufunga?" with "funga tu" among the options.', 'Change a style, close without saving, reopen: the change is gone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI.M6_TAR6_SYMBOL', 'KISW.G6.KUANDI.T3_KUANDIKA_KWA_TARAKIL.MAANDISHI_TARAKILISHI', 'Mixes the symbols used in typing (@ for "at" in an email address, # for a number, % for per cent) or types them as words.', '{"question":"Alama \"@\" hutumika wapi?","wrong_answer":"mwishoni mwa sentensi","correct_answer":"katika anwani ya baruapepe"}'::jsonb, 'The symbols are on the keyboard but never named.', 'The question "Alama "@" hutumika wapi?" with "mwishoni mwa sentensi" among the options.', 'Match each symbol to where it is used, with an example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI.M_NAFSI_PERSON', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI', 'Picks the pronoun of another person (wewe for mimi, wao for sisi).', '{"question":"Juma anamwambia Akinyi, \"___ ni rafiki yangu.\"","wrong_answer":"Mimi","correct_answer":"Wewe"}'::jsonb, 'The child does not ask who speaks and who is spoken to.', 'The question "Juma anamwambia Akinyi, "___ ni rafiki yangu."" with "Mimi" among the options.', 'A sentence with speaker, listener and the one spoken about, all in the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI.M_NAFSI_NUMBER', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI', 'Uses the singular for many or the plural for one (sisi for mimi, ninyi for wewe).', '{"question":"Mama anamwambia mtoto, \"___ unastahili sifa.\"","wrong_answer":"Ninyi","correct_answer":"Wewe"}'::jsonb, 'The child matches the person but not the number.', 'The question "Mama anamwambia mtoto, "___ unastahili sifa."" with "Ninyi" among the options.', 'A sentence to one child with the plural pronoun among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI.M6_NAFSI_SUBJECT', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI', 'Uses a different person in the verb from the pronoun (Mimi anasoma, Sisi wanacheza).', '{"question":"Jaza: Sisi ___ (cheza) mpira.","wrong_answer":"wanacheza","correct_answer":"tunacheza"}'::jsonb, 'The child changes the pronoun but keeps the verb of the third person, the form heard most.', 'The question "Jaza: Sisi ___ (cheza) mpira." with "wanacheza" among the options.', 'Line up pronoun and prefix pairs: mimi ni-, wewe u-, yeye a-, sisi tu-, nyinyi m-, wao wa-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI.M6_NAFSI_OBJECT', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_NAFS.NAFSI', 'Uses the subject pronoun where the object is meant, with no object marker (Mwalimu alisifu mimi).', '{"question":"Ni ipi ni sahihi?","wrong_answer":"Mwalimu alisifu mimi.","correct_answer":"Mwalimu alinisifu (mimi)."}'::jsonb, 'English puts "me" after the verb; Kiswahili puts -ni- inside the verb.', 'The question "Ni ipi ni sahihi?" with "Mwalimu alisifu mimi." among the options.', 'Colour the object marker inside the verb: a-li-ni-sifu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA.M_VWASH_CLASS', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA', 'Uses the demonstrative of another noun class (Hiki ni mti).', '{"question":"___ ni mti wa mwembe.","wrong_answer":"Hii","correct_answer":"Huu"}'::jsonb, 'The child has learned one form and uses it for every noun.', 'The question "___ ni mti wa mwembe." with "Hii" among the options.', 'A gap with several classes among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA.M_VWASH_NUMBER', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA', 'Uses the singular demonstrative for many or the plural for one (Hawa ni mtoto).', '{"question":"___ ni vitabu vya shule.","wrong_answer":"Hiki","correct_answer":"Hivi"}'::jsonb, 'The child matches the class but not the number.', 'The question "___ ni vitabu vya shule." with "Hiki" among the options.', 'A plural noun with the singular form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA.M_VWASH_ADJ', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA', 'Takes the demonstrative after a noun (kitabu hiki) for the pronoun that stands alone (Hiki ni kitabu).', '{"question":"Chagua sentensi yenye kiwakilishi kiashiria (kinasimama peke yake).","wrong_answer":"Kitabu hiki ni kizuri.","correct_answer":"Hiki ni kitabu changu."}'::jsonb, 'The child sees the word hiki and does not look at whether a noun comes before it.', 'The question "Chagua sentensi yenye kiwakilishi kiashiria (kinasimama peke yake)." with "Kitabu hiki ni kizuri." among the options.', 'Two sentences with the same word, one with a noun before it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA.M6_VWASH_DIST', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VIASHIRI.VIWAKILISHI_VIASHIRIA', 'Uses the near one (huyu, hiki) for something far or already mentioned (yule, kile).', '{"question":"Unaonyesha mti ulio mbali mlimani. Unasema?","wrong_answer":"Huu ni mrefu.","correct_answer":"Ule ni mrefu."}'::jsonb, 'The near form is the default the child uses for everything.', 'The question "Unaonyesha mti ulio mbali mlimani. Unasema?" with "Huu ni mrefu." among the options.', 'Point near and far while saying the pairs aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI.M_VWID_CLASS', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI', 'Uses the number with the prefix of another class (Viwili walichelewa for wawili).', '{"question":"Wanafunzi kumi walifika. ___ walichelewa. (wawili kati yao)","wrong_answer":"Viwili","correct_answer":"Wawili"}'::jsonb, 'The child forgets the pronoun takes the prefix of the noun it replaces.', 'The question "Wanafunzi kumi walifika. ___ walichelewa. (wawili kati yao)" with "Viwili" among the options.', 'A sentence about people with the form for things among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI.M_VWID_NO_PREFIX', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI', 'Writes the bare number (Tatu, Wili) with no prefix.', '{"question":"Nilinunua vitabu vitano. ___ nilimpa Wanjiru. (vitatu kati yake)","wrong_answer":"Tatu","correct_answer":"Vitatu"}'::jsonb, 'In English the number never changes.', 'The question "Nilinunua vitabu vitano. ___ nilimpa Wanjiru. (vitatu kati yake)" with "Tatu" among the options.', 'Options with the bare number word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI.M6_VWID_SIX', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI', 'Adds a prefix to six, seven, nine or ten (Wasita walifika).', '{"question":"Jaza: (watu 6) ___ walichelewa.","wrong_answer":"Wasita","correct_answer":"Sita"}'::jsonb, 'The child applies the prefix rule of one to five to every number.', 'The question "Jaza: (watu 6) ___ walichelewa." with "Wasita" among the options.', 'Sort number cards: with a prefix (1-5, 8) and without (6, 7, 9, 10).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI.M6_VWID_AGREE_VERB', 'KISW.G6.SARUFI.T3_VIWAKILISHI_VYA_IDAD.VIWAKILISHI_IDADI', 'Gives the number pronoun the right prefix but the verb another one (Vitatu wamepotea).', '{"question":"Jaza: (vitabu 3) Vitatu ___ potea.","wrong_answer":"wamepotea","correct_answer":"vimepotea"}'::jsonb, 'The child thinks of things lost by people and uses wa-.', 'The question "Jaza: (vitabu 3) Vitatu ___ potea." with "wamepotea" among the options.', 'The verb agrees with the noun the pronoun stands for: vitabu -> vi-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA.M_UAK6_HISI', 'KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA', 'Ends an exclamation or a command with a full stop or a question mark.', '{"question":"Lo! Umefika mapema leo!","wrong_answer":"Lo. Umefika mapema leo.","correct_answer":"Lo! Umefika mapema leo!"}'::jsonb, 'The child ends every sentence the same way.', 'The question "Lo! Umefika mapema leo!" with "Lo. Umefika mapema leo." among the options.', 'A sentence of surprise with a full stop among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA.M_UAK6_RITIFAA', 'KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA', 'Writes ng''ombe or ng''ambo without the ritifaa (ngombe).', '{"question":"Mkulima ana ng''ombe watano.","wrong_answer":"Mkulima ana ngombe watano.","correct_answer":"Mkulima ana ng''ombe watano."}'::jsonb, 'The child does not know the ritifaa marks that ng is one sound.', 'The question "Mkulima ana ng''ombe watano." with "Mkulima ana ngombe watano." among the options.', 'Options with the word spelt both ways.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA.M_UAK6_KOLONI', 'KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA', 'Puts a comma or a full stop where a koloni goes before a list.', '{"question":"Mama alinunua vitu hivi: mchele, sukari na chumvi.","wrong_answer":"Mama alinunua vitu hivi, mchele, sukari na chumvi.","correct_answer":"Mama alinunua vitu hivi: mchele, sukari na chumvi."}'::jsonb, 'The child does not know koloni introduces a list.', 'The question "Mama alinunua vitu hivi: mchele, sukari na chumvi." with "Mama alinunua vitu hivi, mchele, sukari na chumvi." among the options.', 'A sentence that announces a list with a comma among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA.M6_UAK6_RITIFAA_PLACE', 'KISW.G6.SARUFI.T3_UAKIFISHI.ALAMA', 'Puts the ritifaa in the wrong place (n''gombe, ngo''mbe).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"n''gombe","correct_answer":"ng''ombe"}'::jsonb, 'The child knows a mark goes somewhere in the word but not that it sits right after ng.', 'The question "Ni ipi imeandikwa sawa?" with "n''gombe" among the options.', 'The ritifaa marks the sound ng'' as one sound: write ng'' first, then the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA.M_HESH_MISUSE', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA', 'Uses a polite word for the wrong job (asante to ask, pole to thank).', '{"question":"Ukimwomba mwalimu kalamu unasema, \"Mwalimu, nipe kalamu, ___.\"","wrong_answer":"asante","correct_answer":"tafadhali"}'::jsonb, 'The child knows the words but not what each is for.', 'The question "Ukimwomba mwalimu kalamu unasema, "Mwalimu, nipe kalamu, ___."" with "asante" among the options.', 'A situation with all the polite words among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA.M_HESH_RUDE', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA', 'Picks the sentence without a polite word, as if a command were polite.', '{"question":"Ni sentensi ipi ina heshima zaidi?","wrong_answer":"Nisaidie kubeba mzigo huu!","correct_answer":"Tafadhali nisaidie kubeba mzigo huu."}'::jsonb, 'The child does not notice the tone of a command.', 'The question "Ni sentensi ipi ina heshima zaidi?" with "Nisaidie kubeba mzigo huu!" among the options.', 'A request with and without tafadhali or naomba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA.M6_HESH_TITLE', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA', 'Calls an official by the wrong title (Mwalimu for the chief, Daktari for the nurse) or by name only.', '{"question":"Unamsalimu chifu wa eneo lenu. Unasema?","wrong_answer":"Habari mwalimu?","correct_answer":"Shikamoo Bwana Chifu."}'::jsonb, 'The child uses the one title he uses every day (mwalimu).', 'The question "Unamsalimu chifu wa eneo lenu. Unasema?" with "Habari mwalimu?" among the options.', 'List people and their titles: Chifu, Mheshimiwa (MP), Daktari, Muuguzi, Askari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA.M6_HESH_YOU_PLURAL', 'KISW.G6.KUSIKI.T4_HESHIMA_ADABU_NA_VYE.HESHIMA', 'Uses wewe and the singular to an elder where the respectful plural is expected in some communities (Shikamooni / nyinyi).', '{"question":"Unawasalimu wazee wawili. Unasema?","wrong_answer":"Shikamoo","correct_answer":"Shikamooni"}'::jsonb, 'The child does not know the plural form of the respectful greeting.', 'The question "Unawasalimu wazee wawili. Unasema?" with "Shikamoo" among the options.', 'Practise Shikamooni for many elders; Marahabani is the reply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_SHARE', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Shares a password or a personal detail with a friend or a stranger.', '{"question":"Ni hatua ipi ya kiusalama?","wrong_answer":"Kumpa rafiki nenosiri langu","correct_answer":"Kuweka nenosiri langu siri"}'::jsonb, 'The child thinks sharing is friendly.', 'Safe and unsafe steps for a password.', 'Ask who can use your account if they have the password.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_LINK', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Opens every link in a message from someone he does not know.', '{"question":"Ujumbe usiojulikana una kiungo cha zawadi. Ufanye nini?","wrong_answer":"Nikifungue haraka","correct_answer":"Nimwonyeshe mzazi au mwalimu kwanza"}'::jsonb, 'The child is curious and likes a prize.', 'An unknown message with a link.', 'Ask who sent it and whether you asked for it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M_DIG_UNSAFE_SITE', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Searches on any site and gives details to a site that asks for them.', '{"question":"Unatafuta kifungu cha kusoma. Utumie tovuti ipi?","wrong_answer":"Tovuti inayotaka jina na nambari ya simu yangu","correct_answer":"Tovuti ya shule au maktaba iliyopendekezwa na mwalimu"}'::jsonb, 'The child does not ask who runs the site.', 'Safe and unsafe sites.', 'Ask whether the site needs your personal details to read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_FOLDER_T4', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Misimu ya Kenya\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Misimu ya Kenya\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Misimu ya Kenya\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Misimu ya Kenya" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Misimu ya Kenya" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_SEARCH_T4', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu misimu. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu misimu tafadhali","correct_answer":"misimu mvua ndefu fupi Kenya"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu misimu. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu misimu tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_POPUP_T4', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_SITE_T4', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_ORDER_T4', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI.M6_DIG_FAKE', 'KISW.G6.KUSOMA.T4_KUSOMA_KWA_MAPANA.USALAMA_DIJITALI', 'Believes and shares whatever he reads online without checking the source.', '{"question":"Unaona ujumbe mtandaoni: \"Shule zote zitafungwa kesho!\" Ufanye nini?","wrong_answer":"uwatumie marafiki wote haraka","correct_answer":"uthibitishe kwa mwalimu au tovuti rasmi kabla ya kuamini"}'::jsonb, 'The child trusts anything written on a screen.', 'The question "Unaona ujumbe mtandaoni: "Shule zote zitafungwa kesho!" Ufanye nini?" with "uwatumie marafiki wote haraka" among the options.', 'Check one rumour together on an official site.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI.M_BAR6_PART', 'KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI', 'Puts a part of the letter in the wrong place (salamu for kichwa, tarehe for jina).', '{"question":"Mada ya barua rasmi huandikwa katika ___ cha barua.","wrong_answer":"mwili","correct_answer":"kichwa"}'::jsonb, 'The child has met the parts but not what each holds.', 'The question "Mada ya barua rasmi huandikwa katika ___ cha barua." with "mwili" among the options.', 'Parts asked by what they hold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI.M_BAR6_POSITION', 'KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI', 'Puts the sender''s address on the left and the receiver''s on the right.', '{"question":"Anwani ya mwandikaji wa barua rasmi huandikwa upande wa ___ juu ya karatasi.","wrong_answer":"kushoto","correct_answer":"kulia"}'::jsonb, 'The child swaps the two addresses.', 'The question "Anwani ya mwandikaji wa barua rasmi huandikwa upande wa ___ juu ya karatasi." with "kushoto" among the options.', 'Left and right among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI.M_BAR6_FRIENDLY', 'KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI', 'Uses the greeting, ending or words of a friendly letter in a formal one.', '{"question":"Mwisho wa barua rasmi huwa \"Wako ___,\".","wrong_answer":"mpenzi","correct_answer":"mwaminifu"}'::jsonb, 'The child writes to a headteacher as to a friend.', 'The question "Mwisho wa barua rasmi huwa "Wako ___,"." with "mpenzi" among the options.', 'A formal and a friendly ending among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI.M_BAR6_ORDER', 'KISW.G6.KUANDI.T4_BARUA_RASMI.BARUA_RASMI', 'Puts the parts of the letter in the wrong order.', '{"question":"Ni mpangilio upi sahihi wa sehemu za barua rasmi?","wrong_answer":"Salamu, mwili, anwani, kichwa, tarehe, mwisho","correct_answer":"Anwani, tarehe, salamu, kichwa, mwili, mwisho"}'::jsonb, 'The child does not picture the page from top to bottom.', 'The question "Ni mpangilio upi sahihi wa sehemu za barua rasmi?" with "Salamu, mwili, anwani, kichwa, tarehe, mwisho" among the options.', 'Two orderings among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_ONEADDR_T4', 'KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Writes only one address, or puts the receiver''s address at the top right.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja, ya mwandishi","correct_answer":"mbili: ya mwandishi (kulia juu) na ya mpokeaji (kushoto)"}'::jsonb, 'The friendly letter has one address and the child carries it over.', 'The question "Barua rasmi ina anwani ngapi?" with "moja, ya mwandishi" among the options.', 'Label both addresses on a model; the child writes his own and the receiver''s on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_NOREF_T4', 'KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Leaves out the subject line (KUH: or YAH:) or writes it as a long sentence.', '{"question":"Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kupanda miti shuleni?","wrong_answer":"Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi.","correct_answer":"KUH: OMBI LA KUPANDA MITI SHULENI"}'::jsonb, 'The child does not know the reader of an official letter needs the subject before reading.', 'The question "Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kupanda miti shuleni?" with "Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi." among the options.', 'Underline the KUH: line on three real letters; it is short and in capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_CASUAL_T4', 'KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Uses friendly words in an official letter (Mpendwa rafiki, Hujambo?, Wako akupendaye).', '{"question":"Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?","wrong_answer":"Hujambo mwalimu wangu mpendwa!","correct_answer":"Kwa Mwalimu Mkuu,"}'::jsonb, 'The friendly letter is the first letter learnt and its words come first.', 'The question "Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?" with "Hujambo mwalimu wangu mpendwa!" among the options.', 'Sort salamu and closing cards into "kirafiki" and "rasmi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_SIGNOFF_T4', 'KISW.G6.KUANDI.T4_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Ends with only a first name and no signature, or with "Ni mimi rafiki yako".', '{"question":"Barua rasmi humalizika vipi?","wrong_answer":"Ni mimi rafiki yako, Wanjiku","correct_answer":"Wako mtiifu, sahihi, na jina kamili: Wanjiku Kamau"}'::jsonb, 'The friendly closing is a habit.', 'The question "Barua rasmi humalizika vipi?" with "Ni mimi rafiki yako, Wanjiku" among the options.', 'Model the closing block (Wako mtiifu, sahihi, jina kamili) and have the child copy it once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA.M_YAYA_LI', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA', 'Uses li- with a ma- noun because it starts with ma- (maji limeisha).', '{"question":"Maji ___meisha kisimani.","wrong_answer":"li","correct_answer":"ya"}'::jsonb, 'The child learned that ma- goes with li-, which is true only for the plural of nouns that have a singular.', 'The question "Maji ___meisha kisimani." with "li" among the options.', 'Ask "Je, kuna neno jiji, au jimaji?" Maji has no singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA.M_YAYA_OTHER', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA', 'Uses u-, i-, zi- or vi- with a YA-YA noun.', '{"question":"Maziwa ___meichacha jikoni.","wrong_answer":"i","correct_answer":"ya"}'::jsonb, 'The child uses the prefix of the class he knows best.', 'The question "Maziwa ___meichacha jikoni." with "i" among the options.', 'A gap with several prefixes among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA.M_YAYA_A', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA', 'Uses a- as for a person or animal (maziwa ameichacha).', '{"question":"Maziwa ___meichacha jikoni.","wrong_answer":"a","correct_answer":"ya"}'::jsonb, 'The child treats the noun like a living thing.', 'The question "Maziwa ___meichacha jikoni." with "a" among the options.', 'A gap with a- among the options for a thing noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA.M_YAYA_NOUN', 'KISW.G6.SARUFI.T4_NGELI_YA_YA_YA.YA_YA', 'Picks a noun of another class as a YA-YA noun.', '{"question":"Ni nomino ipi ni ya ngeli ya YA-YA?","wrong_answer":"kitabu","correct_answer":"maji"}'::jsonb, 'The child cannot yet tell YA-YA nouns by their agreement.', 'The question "Ni nomino ipi ni ya ngeli ya YA-YA?" with "kitabu" among the options.', 'Options with nouns from different classes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI.M_MET_LITERAL', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI', 'Reads the methali word for word.', '{"question":"Mchumia juani hulia kivulini. Maana yake ni nini?","wrong_answer":"Anayekaa juani hulia","correct_answer":"Anayefanya kazi kwa bidii hufurahia matunda yake baadaye"}'::jsonb, 'The child does not know that a methali carries a second meaning.', 'A meaning question with a literal option.', 'Ask what lesson the methali teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI.M_MET_WRONG_LESSON', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI', 'Gives the lesson of another methali.', '{"question":"Haba na haba hujaza kibaba. Maana yake ni nini?","wrong_answer":"Umoja ni nguvu","correct_answer":"Vitu vidogo vikiongezwa polepole huwa vingi"}'::jsonb, 'The child knows methali but swaps their lessons.', 'The meaning of a different methali as an option.', 'Ask what the words say about little and little.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI.M_MET_WRONG_END', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI', 'Completes the methali with a word that does not belong to it.', '{"question":"Haba na haba hujaza ___.","wrong_answer":"chupa","correct_answer":"kibaba"}'::jsonb, 'The child remembers the beginning but not the end.', 'A gap where a plausible wrong ending is an option.', 'Say the whole methali again from the beginning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI.M6_MET_OPPOSITE_LESSON', 'KISW.G6.KUSIKI.T5_METHALI_KUFIKIA_MWIS.METHALI', 'Gives the opposite lesson (Kidole kimoja hakivunji chawa: one person is enough).', '{"question":"Maana ya \"Kidole kimoja hakivunji chawa\" ni?","wrong_answer":"mtu mmoja anaweza kufanya kazi yote","correct_answer":"ushirikiano unahitajika kufanikisha jambo"}'::jsonb, 'The child reads "hakivunji" quickly and misses the negative.', 'The question "Maana ya "Kidole kimoja hakivunji chawa" ni?" with "mtu mmoja anaweza kufanya kazi yote" among the options.', 'Read the methali slowly and mark the negative word; say what one finger cannot do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA.M_SHA_AINA_SWAP', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA', 'Gives the name of another kind of poem for the number of lines (tathlitha for tathnia).', '{"question":"Ubeti wenye mishororo miwili huitwa ___.","wrong_answer":"tathlitha","correct_answer":"tathnia"}'::jsonb, 'The child has the names but not the numbers behind them.', 'The question "Ubeti wenye mishororo miwili huitwa ___." with "tathlitha" among the options.', 'The number of lines asked with all three names among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA.M_SHA_AINA_COUNT', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA', 'Names the kind of a stanza shown without counting its lines.', '{"question":"Ubeti huu ni wa aina gani? \"Mvua imenyesha, / Mito imejaa.\"","wrong_answer":"tathlitha","correct_answer":"tathnia"}'::jsonb, 'The child guesses from the look of the stanza.', 'The question "Ubeti huu ni wa aina gani? "Mvua imenyesha, / Mito imejaa."" with "tathlitha" among the options.', 'A short stanza with the three names among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA.M_SHA_UKWAPI_SWAP', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA', 'Swaps ukwapi (the first part of a line) and utao (the second).', '{"question":"Kipande cha kwanza cha mshororo wa shairi huitwa ___.","wrong_answer":"utao","correct_answer":"ukwapi"}'::jsonb, 'The child knows the two names but not their order.', 'The question "Kipande cha kwanza cha mshororo wa shairi huitwa ___." with "utao" among the options.', 'Both names among the options for the first or the second part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA.M_SHA_PART_MIX', 'KISW.G6.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.SHAIRI_AINA', 'Gives vina or mizani for the parts of a line.', '{"question":"Kipande cha pili cha mshororo wa shairi huitwa ___.","wrong_answer":"vina","correct_answer":"utao"}'::jsonb, 'The child mixes the parts of a line with its sounds and counts.', 'The question "Kipande cha pili cha mshororo wa shairi huitwa ___." with "vina" among the options.', 'Options with vina and mizani.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA.M_INS_WASIFU_STORY', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA', 'Takes a text that describes a person (wasifu) for a story (masimulizi).', '{"question":"Kifungu kinaelezea sura, tabia na maisha ya mtu. Ni insha ya aina gani?","wrong_answer":"masimulizi","correct_answer":"wasifu"}'::jsonb, 'Both kinds can mention a person.', 'Short texts: one describing a person, one telling events.', 'Ask whether the text tells what happened in order, or tells who someone is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA.M_INS_MAELEZO_STORY', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA', 'Takes a text that explains how something is done (maelezo) for a story.', '{"question":"Kifungu kinaeleza hatua za kupika uji. Ni insha ya aina gani?","wrong_answer":"masimulizi","correct_answer":"maelezo"}'::jsonb, 'The child sees a sequence in both.', 'A recipe-like text and a story.', 'Ask whether the writer says "what happened" or "how to do it".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA.M_INS_STORY_WASIFU', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA', 'Takes a story of events for a description of a person.', '{"question":"Kifungu kinasimulia kilichotokea Jumamosi kijijini. Ni insha ya aina gani?","wrong_answer":"wasifu","correct_answer":"masimulizi"}'::jsonb, 'A story has a person in it.', 'A story about a person doing things.', 'Does the text tell events in order?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STORY_T5', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kudumisha Umoja Shuleni\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, tuwakaribishe wanafunzi wapya kutoka jamii zote."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kudumisha Umoja Shuleni"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_DETAIL_T5', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kudumisha Umoja Shuleni\"?","wrong_answer":"Umoja ni mzuri.","correct_answer":"Kwanza, tuwakaribishe wanafunzi wapya kutoka jamii zote."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kudumisha Umoja Shuleni"?" with "Umoja ni mzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STEPS_T5', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kudumisha Umoja Shuleni\"?","wrong_answer":"tatua migogoro kwa amani, heshimu tamaduni, shirikiana katika kazi, wakaribishe wageni","correct_answer":"wakaribishe wageni, shirikiana katika kazi, heshimu tamaduni, tatua migogoro kwa amani"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kudumisha Umoja Shuleni"?" with "tatua migogoro kwa amani, heshimu tamaduni, shirikiana katika kazi, wakaribishe wageni" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_OFFTOPIC_T5', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kudumisha Umoja Shuleni\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, tuwakaribishe wanafunzi wapya kutoka jamii zote."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kudumisha Umoja Shuleni", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_PARAS_T5', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kudumisha Umoja Shuleni\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kudumisha Umoja Shuleni" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA.M6_INS_MAELEZO_WASIFU', 'KISW.G6.KUANDI.T5_INSHA_ZA_MAELEZO.AINA_ZA_INSHA', 'Takes a maelezo of how to do something for a wasifu, or a wasifu for a maelezo.', '{"question":"Matini inayoanza \"Kwanza, chukua jembe...\" ni ya aina gani?","wrong_answer":"wasifu","correct_answer":"maelezo"}'::jsonb, 'Both describe; the child does not ask whether it describes a thing or explains how to do something.', 'The question "Matini inayoanza "Kwanza, chukua jembe..." ni ya aina gani?" with "wasifu" among the options.', 'Ask: does it describe how something is (wasifu) or how it is done (maelezo)?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U.M_UU_PLURAL', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U', 'Uses ya- or zi- with a U-U noun as if it had a plural (uji yametiwa).', '{"question":"Uji ___metiwa sukari.","wrong_answer":"ya","correct_answer":"u"}'::jsonb, 'The child assumes every noun can be many.', 'The question "Uji ___metiwa sukari." with "ya" among the options.', 'Ask "Je, tunasema ujiuji? Uji una wingi?" It has none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U.M_UU_OTHER', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U', 'Uses i-, li- or another prefix with a U-U noun.', '{"question":"Ugali ___meiva sasa.","wrong_answer":"i","correct_answer":"u"}'::jsonb, 'The child uses the prefix of a class he knows better.', 'The question "Ugali ___meiva sasa." with "i" among the options.', 'A gap with several prefixes among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U.M_UU_NOUN', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U', 'Picks a noun of another class as a U-U noun.', '{"question":"Ni nomino ipi ni ya ngeli ya U-U?","wrong_answer":"kitabu","correct_answer":"uji"}'::jsonb, 'The child cannot yet tell U-U nouns by their agreement.', 'The question "Ni nomino ipi ni ya ngeli ya U-U?" with "kitabu" among the options.', 'Options with nouns from different classes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U.M6_UU_UYA', 'KISW.G6.SARUFI.T5_NGELI_YA_U_U.U_U', 'Gives a U-U noun a ma- plural (umoja -> maumoja, uji -> mauji).', '{"question":"Wingi wa \"umoja\" ni upi?","wrong_answer":"maumoja","correct_answer":"umoja (haubadiliki)"}'::jsonb, 'U-YA nouns like ugonjwa/magonjwa teach the child that u- nouns take ma-.', 'The question "Wingi wa "umoja" ni upi?" with "maumoja" among the options.', 'Test: can you count it? Umoja, uji, ugali are not counted; they stay U-U.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA.M6_SHU_SOUND', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA', 'Says the target sound of the poem as the close sound (nchi as chi, ng''ombe as gombe) while reciting.', '{"question":"Neno \"njia\" katika shairi linatamkwa vipi?","wrong_answer":"jia","correct_answer":"njia"}'::jsonb, 'The nasal is quick and the child drops it when reciting fast.', 'The question "Neno "njia" katika shairi linatamkwa vipi?" with "jia" among the options.', 'Slow the line down; say the nasal clearly, then speed up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA.M6_SHU_GENDER_LITERAL', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA', 'Takes a line about equal roles literally (both must do the same job every day).', '{"question":"Shairi linasema: \"Kazi ya nyumba si ya mama peke yake.\" Maana yake ni?","wrong_answer":"mama asifanye kazi ya nyumba","correct_answer":"wote nyumbani, wake kwa waume, washiriki kazi"}'::jsonb, 'The child reads the negative as a rule against the mother.', 'The question "Shairi linasema: "Kazi ya nyumba si ya mama peke yake." Maana yake ni?" with "mama asifanye kazi ya nyumba" among the options.', 'Restate the line in a positive sentence together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA.M6_SHU_WORD', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA', 'Gives the everyday meaning of a word where the poem uses a figurative one (bega as the shoulder only, where it means support).', '{"question":"\"Tushikane bega kwa bega.\" Maana ya \"bega kwa bega\" ni?","wrong_answer":"kugusa mabega","correct_answer":"kushirikiana kwa usawa"}'::jsonb, 'The child knows the body word and does not test it against the line.', 'The question ""Tushikane bega kwa bega." Maana ya "bega kwa bega" ni?" with "kugusa mabega" among the options.', 'Read the line with each meaning in place; keep the one that makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA.M6_SHU_OUTSIDE', 'KISW.G6.KUSIKI.T6_MATAMSHI_BORA.SHAIRI_USAWA', 'Answers a question about the poem from his own view, not from the poem.', '{"question":"Kwa mujibu wa shairi, kwa nini wasichana na wavulana wasome wote?","wrong_answer":"kwa sababu wazazi wanataka","correct_answer":"kwa sababu elimu ni haki ya kila mtoto"}'::jsonb, 'The topic is one the child has views on.', 'The question "Kwa mujibu wa shairi, kwa nini wasichana na wavulana wasome wote?" with "kwa sababu wazazi wanataka" among the options.', 'Ask for the line that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M6_MAK_CRITERIA', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Chooses an article by its length or colour, not by its topic and his reading level.', '{"question":"Ni kigezo kipi bora cha kuchagua makala maktabani?","wrong_answer":"makala marefu zaidi","correct_answer":"mada inayokuvutia na lugha unayoielewa"}'::jsonb, 'Nobody has named the criteria; the child picks what looks impressive.', 'The question "Ni kigezo kipi bora cha kuchagua makala maktabani?" with "makala marefu zaidi" among the options.', 'List criteria together (mada, kiwango, mwandishi, tarehe) and use them on three real articles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M6_MAK_OLD', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Chooses an old article for news that changes (last year''s statistics) without looking at the date.', '{"question":"Unatafuta habari mpya kuhusu usawa wa kijinsia shuleni. Uangalie nini kwanza?","wrong_answer":"picha ya jalada","correct_answer":"tarehe ya makala"}'::jsonb, 'The child does not know information goes out of date.', 'The question "Unatafuta habari mpya kuhusu usawa wa kijinsia shuleni. Uangalie nini kwanza?" with "picha ya jalada" among the options.', 'Compare two articles on the same topic from different years.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M6_MAK_EXAMPLE', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Gives an example in the article as its main point.', '{"question":"Wazo kuu la makala \"Wasichana Katika Sayansi\" ni lipi?","wrong_answer":"Akinyi alishinda tuzo ya sayansi.","correct_answer":"Wasichana na wavulana wanaweza kufaulu katika sayansi."}'::jsonb, 'The example is a little story and stays in memory.', 'The question "Wazo kuu la makala "Wasichana Katika Sayansi" ni lipi?" with "Akinyi alishinda tuzo ya sayansi." among the options.', 'Ask: is this the point, or a case that shows the point?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA.M6_MAK_OPINION', 'KISW.G6.KUSOMA.T6_KUSOMA_KWA_KINA.MAKALA_MAKTABA', 'Takes the writer''s opinion for a fact, or a fact for an opinion.', '{"question":"Ni sentensi ipi ni maoni ya mwandishi?","wrong_answer":"Shule yetu ina wanafunzi mia tano.","correct_answer":"Shule yetu ndiyo bora zaidi nchini."}'::jsonb, 'Both are stated in the article with the same confidence.', 'The question "Ni sentensi ipi ni maoni ya mwandishi?" with "Shule yetu ina wanafunzi mia tano." among the options.', 'Ask: can it be checked? A fact can; an opinion is what someone thinks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU.M_INS6_PART', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU', 'Names the wrong part of the insha (puts the ending in the introduction).', '{"question":"Sehemu ya mwisho ya insha huitwa ___.","wrong_answer":"utangulizi","correct_answer":"hitimisho"}'::jsonb, 'The child knows the names of the parts but not their order.', 'The question "Sehemu ya mwisho ya insha huitwa ___." with "utangulizi" among the options.', 'A part asked by its place (first, middle, last) with all the names among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_STORY_T6', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Dada Yangu Mhandisi\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Dada yangu ni mrefu, mchangamfu, na huvaa kofia ngumu ya njano kazini."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Dada Yangu Mhandisi"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_DETAIL_T6', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Dada Yangu Mhandisi\"?","wrong_answer":"Dada yangu ni mzuri.","correct_answer":"Dada yangu ni mrefu, mchangamfu, na huvaa kofia ngumu ya njano kazini."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Dada Yangu Mhandisi"?" with "Dada yangu ni mzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_AGREE_T6', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Ana mikono mrefu.","correct_answer":"Ana mikono mirefu."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Ana mikono mrefu." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_OFFTOPIC_T6', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Dada Yangu Mhandisi\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Dada yangu ni mrefu, mchangamfu, na huvaa kofia ngumu ya njano kazini."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Dada Yangu Mhandisi", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU.M6_INS_PARAS_T6', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.INSHA_WASIFU', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Dada Yangu Mhandisi\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Dada Yangu Mhandisi" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU.M6_MW_INTRO_DETAIL', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU', 'Puts all the detail in the utangulizi and leaves the kiini with one line.', '{"question":"Utangulizi wa insha ya wasifu hufanya nini?","wrong_answer":"hueleza sifa zote za mtu","correct_answer":"humtambulisha mtu au kitu kwa ufupi"}'::jsonb, 'The child starts with everything he knows and runs out for the middle.', 'The question "Utangulizi wa insha ya wasifu hufanya nini?" with "hueleza sifa zote za mtu" among the options.', 'Plan: utangulizi one or two sentences; kiini a paragraph for each feature.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU.M6_MW_ORDER_FEATURES', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU', 'Describes features in no order (face, job, eyes, home, hair), so the picture is broken.', '{"question":"Ni mpangilio upi bora wa kiini cha wasifu wa mtu?","wrong_answer":"macho, kazi, nywele, nyumbani, uso","correct_answer":"umbo na sura, tabia, kazi"}'::jsonb, 'The child writes features as they come to mind.', 'The question "Ni mpangilio upi bora wa kiini cha wasifu wa mtu?" with "macho, kazi, nywele, nyumbani, uso" among the options.', 'Group features: appearance, character, work; one paragraph each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU.M6_MW_NO_CLOSE', 'KISW.G6.KUANDI.T6_INSHA_YA_WASIFU.MUUNDO_WASIFU', 'Ends without a hitimisho that sums up why the person or thing matters.', '{"question":"Ni hitimisho lipi linafaa katika wasifu wa mwalimu wako?","wrong_answer":"Mwisho.","correct_answer":"Kwa sababu ya bidii yake, mwalimu wetu ni kielelezo chema kwetu sote."}'::jsonb, 'The child stops when the features run out.', 'The question "Ni hitimisho lipi linafaa katika wasifu wa mwalimu wako?" with "Mwisho." among the options.', 'Ask: what do you want the reader to remember about this person?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I.M_II_PLURAL', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I', 'Uses zi- with an I-I noun as if it were a plural (afya zimeimarika).', '{"question":"Afya ___meimarika baada ya matibabu.","wrong_answer":"zi","correct_answer":"i"}'::jsonb, 'The child ties i- and zi- together as the pair for one and many.', 'The question "Afya ___meimarika baada ya matibabu." with "zi" among the options.', 'Ask "Je, tunasema afyaafya? Afya ni kitu cha kuhesabu?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I.M_II_OTHER', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I', 'Uses u-, li- or another prefix with an I-I noun.', '{"question":"Njaa ___nauma tumboni.","wrong_answer":"u","correct_answer":"i"}'::jsonb, 'The child uses the prefix of a class he knows better.', 'The question "Njaa ___nauma tumboni." with "u" among the options.', 'A gap with several prefixes among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I.M_II_NOUN', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I', 'Picks a noun of another class as an I-I noun.', '{"question":"Ni nomino ipi ni ya ngeli ya I-I?","wrong_answer":"kitabu","correct_answer":"afya"}'::jsonb, 'The child cannot yet tell I-I nouns by their agreement.', 'The question "Ni nomino ipi ni ya ngeli ya I-I?" with "kitabu" among the options.', 'Options with nouns from different classes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I.M6_II_IZI', 'KISW.G6.SARUFI.T6_NGELI_YA_I_I.I_I', 'Treats an I-I noun as I-ZI and gives it zi- in a "plural" (sukari zimeisha).', '{"question":"Jaza: Sukari ___ (isha).","wrong_answer":"zimeisha","correct_answer":"imeisha"}'::jsonb, 'Most n- nouns the child knows are I-ZI with a zi- plural.', 'The question "Jaza: Sukari ___ (isha)." with "zimeisha" among the options.', 'Test: can you count it? Sukari, chai, afya are not counted; they stay i-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T7_NAHAU.NAHAU.M_NAH_LITERAL', 'KISW.G6.KUSIKI.T7_NAHAU.NAHAU', 'Reads the nahau word for word.', '{"question":"\"Kukata tamaa\" maana yake ni nini?","wrong_answer":"kukata kamba ya tamaa","correct_answer":"kuacha kuwa na matumaini"}'::jsonb, 'The child does not know that a nahau has its own meaning.', 'A meaning question with a literal option.', 'Ask whether anyone really cuts tamaa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T7_NAHAU.NAHAU.M_NAH_WRONG_MEANING', 'KISW.G6.KUSIKI.T7_NAHAU.NAHAU', 'Gives the meaning of another nahau.', '{"question":"\"Kula chumvi\" maana yake ni nini?","wrong_answer":"kuwa na hamu ya kula","correct_answer":"kuwa na umri mkubwa na uzoefu"}'::jsonb, 'The child knows several nahau but swaps meanings.', 'The meaning of another nahau as an option.', 'Ask what experience chumvi stands for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T7_NAHAU.NAHAU.M_NAH_WRONG_WORD', 'KISW.G6.KUSIKI.T7_NAHAU.NAHAU', 'Completes the nahau with a different word (kukata moyo for kukata tamaa).', '{"question":"Usikate ___ ukishindwa mara moja.","wrong_answer":"kamba","correct_answer":"tamaa"}'::jsonb, 'The child remembers the shape but changes a word.', 'A nahau gap where a near word is an option.', 'Recite the whole nahau.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T7_NAHAU.NAHAU.M6_NAH_USE', 'KISW.G6.KUSIKI.T7_NAHAU.NAHAU', 'Uses a nahau of work in a sentence where its meaning does not fit (Alijifunga kibwebwe kulala).', '{"question":"Ni sentensi ipi imetumia \"kujifunga kibwebwe\" ipasavyo?","wrong_answer":"Alijifunga kibwebwe akalala.","correct_answer":"Alijifunga kibwebwe akamaliza kazi ya shamba."}'::jsonb, 'The child knows the words, not the situation.', 'The question "Ni sentensi ipi imetumia "kujifunga kibwebwe" ipasavyo?" with "Alijifunga kibwebwe akalala." among the options.', 'Say the meaning (to get ready to work hard) and test the sentence against it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_COVER_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu majanga na jinsi ya kuyazuia. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu majanga na jinsi ya kuyazuia. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_LEVEL_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Mafuriko ya Budalang''i\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Mafuriko ya Budalang''i" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_TITLEMSG_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Mafuriko ya Budalang''i\" ni upi?","wrong_answer":"Mafuriko ya Budalang''i","correct_answer":"Tukijiandaa mapema na kufuata maagizo, tunapunguza madhara ya majanga."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Mafuriko ya Budalang''i" ni upi?" with "Mafuriko ya Budalang''i" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_DETAIL_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu majanga na jinsi ya kuyazuia?","wrong_answer":"Maji yalifika kwenye madirisha ya nyumba.","correct_answer":"Tukijiandaa mapema na kufuata maagizo, tunapunguza madhara ya majanga."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu majanga na jinsi ya kuyazuia?" with "Maji yalifika kwenye madirisha ya nyumba." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_KIND_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_WORD_T7', 'KISW.G6.KUSOMA.T7_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (tahadhari).', '{"question":"Katika matini: \"Wanakijiji walipewa tahadhari kabla ya mvua kubwa kunyesha.\" Neno \"tahadhari\" lina maana gani?","wrong_answer":"tarehe ya mkutano","correct_answer":"onyo la mapema kuhusu hatari"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Wanakijiji walipewa tahadhari kabla ya mvua kubwa kunyesha." Neno "tahadhari" lina maana gani?" with "tarehe ya mkutano" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STORY_T7', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kujikinga na Moto Nyumbani\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, zima jiko la mkaa kabla ya kulala."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kujikinga na Moto Nyumbani"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_DETAIL_T7', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kujikinga na Moto Nyumbani\"?","wrong_answer":"Moto ni hatari.","correct_answer":"Kwanza, zima jiko la mkaa kabla ya kulala."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kujikinga na Moto Nyumbani"?" with "Moto ni hatari." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STEPS_T7', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kujikinga na Moto Nyumbani\"?","wrong_answer":"jua njia ya kutoka, usiache taa ikiwaka, weka viberiti mbali na watoto, zima jiko","correct_answer":"zima jiko, weka viberiti mbali na watoto, usiache taa ikiwaka, jua njia ya kutoka"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kujikinga na Moto Nyumbani"?" with "jua njia ya kutoka, usiache taa ikiwaka, weka viberiti mbali na watoto, zima jiko" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_OFFTOPIC_T7', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kujikinga na Moto Nyumbani\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, zima jiko la mkaa kabla ya kulala."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kujikinga na Moto Nyumbani", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_PARAS_T7', 'KISW.G6.KUANDI.T7_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kujikinga na Moto Nyumbani\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kujikinga na Moto Nyumbani" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU.M_PKM_MIX', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU', 'Uses the wrong one of pa-, ku-, mu- for the place (kule pana).', '{"question":"Kule shambani ___ mazao mengi.","wrong_answer":"pana","correct_answer":"kuna"}'::jsonb, 'The child does not read the word of place (pale, kule, humu).', 'The question "Kule shambani ___ mazao mengi." with "pana" among the options.', 'A sentence with pale, kule or humu and all three forms among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU.M_PKM_CLASS', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU', 'Uses the prefix of the noun (una, ina) where the place needs pa-, ku- or mu-.', '{"question":"Kule shambani ___ mazao mengi.","wrong_answer":"ina","correct_answer":"kuna"}'::jsonb, 'The child follows the noun and not the place.', 'The question "Kule shambani ___ mazao mengi." with "ina" among the options.', 'Options with u- and i- forms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU.M6_PKM_NI', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU', 'Uses the noun''s own prefix with a place noun in -ni (nyumbani imesafishwa for nyumbani kumesafishwa).', '{"question":"Jaza: Shuleni ___ (safishwa).","wrong_answer":"imesafishwa","correct_answer":"kumesafishwa / pamesafishwa"}'::jsonb, 'The child sees the noun shule (I-ZI) and keeps its prefix.', 'The question "Jaza: Shuleni ___ (safishwa)." with "imesafishwa" among the options.', 'A place in -ni moves to PA-KU-MU: shuleni pa- (exact place), ku- (general), mu- (inside).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU.M6_PKM_MU_INSIDE', 'KISW.G6.SARUFI.T7_NGELI_YA_PA_KU_MU.PA_KU_MU', 'Uses ku- or pa- for inside a thing where mu- is needed (ndani ya nyumba kuna giza for mna giza).', '{"question":"Jaza: Ndani ya chumba ___ giza.","wrong_answer":"pana","correct_answer":"mna"}'::jsonb, 'Kuna is the common "there is" and the child uses it everywhere.', 'The question "Jaza: Ndani ya chumba ___ giza." with "pana" among the options.', 'Act: inside a box (mu-), at a spot (pa-), around/far (ku-).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T8_VISAWE.VISAWE.M_VIS_OPPOSITE', 'KISW.G6.KUSIKI.T8_VISAWE.VISAWE', 'Picks the opposite where the same meaning is asked.', '{"question":"Kisawe cha \"furaha\" ni ___.","wrong_answer":"huzuni","correct_answer":"bashasha"}'::jsonb, 'The child links furaha and huzuni because they go together.', 'A synonym question with the opposite as an option.', 'Ask whether the two words mean the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T8_VISAWE.VISAWE.M_VIS_RELATED', 'KISW.G6.KUSIKI.T8_VISAWE.VISAWE', 'Picks a word about the same topic but with a different meaning.', '{"question":"Kisawe cha \"huzuni\" ni ___.","wrong_answer":"kilio","correct_answer":"simanzi"}'::jsonb, 'The child picks what goes with the word, not what means the same.', 'A related word as an option.', 'Could you swap the two words in a sentence and keep the same meaning?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T8_VISAWE.VISAWE.M_VIS_LOOKALIKE', 'KISW.G6.KUSIKI.T8_VISAWE.VISAWE', 'Picks a word that looks or sounds like the word.', '{"question":"Kisawe cha \"haraka\" ni ___.","wrong_answer":"harufu","correct_answer":"upesi"}'::jsonb, 'The child goes by the first letters.', 'A look-alike word as an option.', 'Say what each word means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T8_VISAWE.VISAWE.M_VIS_MIXED', 'KISW.G6.KUSIKI.T8_VISAWE.VISAWE', 'Picks a group that has one opposite or unrelated word among the synonyms.', '{"question":"Ni kundi lipi lina maneno yote yenye maana sawa na \"furaha\"?","wrong_answer":"bashasha, huzuni, raha, tabasamu","correct_answer":"bashasha, shangwe, raha, nderemo"}'::jsonb, 'The child checks the first words of the group and not every word.', 'The question "Ni kundi lipi lina maneno yote yenye maana sawa na "furaha"?" with "bashasha, huzuni, raha, tabasamu" among the options.', 'A group with three synonyms and one opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_STAGE_AS_SPEECH', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Reads the words in brackets (what to do on stage) as words a character says.', '{"question":"Maelekezo ya jukwaani katika igizo ni yapi?","wrong_answer":"Mama: Nenda sokoni.","correct_answer":"(Anafungua mlango)"}'::jsonb, 'The child reads a play as a story.', 'A play with brackets and spoken lines.', 'Brackets tell the actor what to do, not what to say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_STORY', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Does not tell a play from a story.', '{"question":"Ni kipi kati ya hivi ni igizo?","wrong_answer":"Wanjiru alienda sokoni.","correct_answer":"Wanjiru: Naenda sokoni."}'::jsonb, 'The child sees a short text and does not look at the form.', 'A play and a story on the same event.', 'Look for the speaker names with a colon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_WRONG_SPEAKER', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives a character who did not say the line.', '{"question":"Nani alisema \"Nitakuletea maji\"?","wrong_answer":"Baba","correct_answer":"Mwajuma"}'::jsonb, 'The child does not follow the names before the colons.', 'A who-said-it question.', 'Find the line and read the name before it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_DETAIL', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives a wrong detail of the play (the place, the thing bought).', '{"question":"Akinyi alienda wapi?","wrong_answer":"jikoni","correct_answer":"sokoni"}'::jsonb, 'The child remembers a place named near the question.', 'A where-or-what question with another detail of the play.', 'Find the line where it is said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO.M_IGI_VOCAB', 'KISW.G6.KUSOMA.T8_KUSOMA_KWA_UFAHAMU.IGIZO', 'Gives the wrong meaning of a word in the play.', '{"question":"Neno \"kuandamana\" lina maana gani katika igizo?","wrong_answer":"kukimbia peke yake","correct_answer":"kwenda pamoja na mtu"}'::jsonb, 'The child guesses from the look of the word.', 'A meaning question for a word in the play.', 'Read the line where the word is used and think who goes with whom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_FACTS_T8', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Kasa Aliyeokolewa\"?","wrong_answer":"Kasa ni mnyama anayeishi majini kwa miaka mingi.","correct_answer":"Tulimwona kasa amenaswa kwenye nyavu za wavuvi."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Kasa Aliyeokolewa"?" with "Kasa ni mnyama anayeishi majini kwa miaka mingi." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_TENSE_T8', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Kasa Aliyeokolewa\"?","wrong_answer":"Tunamwona kasa amenaswa kwenye nyavu za wavuvi.","correct_answer":"Tulimwona kasa amenaswa kwenye nyavu za wavuvi."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Kasa Aliyeokolewa"?" with "Tunamwona kasa amenaswa kwenye nyavu za wavuvi." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_ORDER_T8', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Kasa Aliyeokolewa\"?","wrong_answer":"kasa aliogelea baharini, tulikata nyavu, tuliwaita wavuvi, tulimwona kasa","correct_answer":"tulimwona kasa, tuliwaita wavuvi, tulikata nyavu, kasa aliogelea baharini"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Kasa Aliyeokolewa"?" with "kasa aliogelea baharini, tulikata nyavu, tuliwaita wavuvi, tulimwona kasa" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_END_T8', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Kasa Aliyeokolewa\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Kasa Aliyeokolewa"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_DIALOGUE_T8', 'KISW.G6.KUANDI.T8_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes what a character said without the alama za usemi and the comma (Mama alisema njoo hapa).', '{"question":"Ni sentensi ipi imeandikwa sawa?","wrong_answer":"Mama alisema njoo hapa haraka.","correct_answer":"Mama alisema, \"Njoo hapa haraka.\""}'::jsonb, 'Speech is written as the child hears it, with no sign of where the words begin and end.', 'The question "Ni sentensi ipi imeandikwa sawa?" with "Mama alisema njoo hapa haraka." among the options.', 'Underline the exact words said; put them inside the marks, with a comma before and a capital inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO.M_MNY_BASE', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO', 'Keeps the simple verb where a longer form is needed (hupika for hupikiana).', '{"question":"Majirani hao ___ chakula kila Jumapili. (kila mmoja humpikia mwenzake)","wrong_answer":"hupika","correct_answer":"hupikiana"}'::jsonb, 'The child reads the verb and not what the sentence says about who does it for whom.', 'The question "Majirani hao ___ chakula kila Jumapili. (kila mmoja humpikia mwenzake)" with "hupika" among the options.', 'Ask "Nani anampikia nani?" If each cooks for the other, the verb needs -ana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO.M_MNY_ONEWAY', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO', 'Uses the verb for one doing it for another (hupikia) where each does it for the other (hupikiana).', '{"question":"Otieno na Achieng ___ barua kila mwezi.","wrong_answer":"huandikia","correct_answer":"huandikiana"}'::jsonb, 'The child leaves out -ana.', 'The question "Otieno na Achieng ___ barua kila mwezi." with "huandikia" among the options.', 'A sentence in which two people do the same for each other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO.M_MNY_WRONG_FORM', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO', 'Picks a verb form that does not fit the meaning (huandikisha for huandikiana).', '{"question":"Mwalimu ___ watoto kuimba wimbo mpya. (huwafanya waimbe)","wrong_answer":"huimbiana","correct_answer":"huimbisha"}'::jsonb, 'The child mixes the endings -ana, -isha and -ua.', 'The question "Mwalimu ___ watoto kuimba wimbo mpya. (huwafanya waimbe)" with "huimbiana" among the options.', 'Options with each ending and a gloss in brackets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO.M6_MNY_TENDUA_ALL', 'KISW.G6.SARUFI.T8_MNYAMBULIKO_WA.MNYAMBULIKO', 'Makes the reversive (kutendua) of any verb with -ua, even where it does not exist (kulaua, kusomua).', '{"question":"Kauli ya kutendua ya \"funga\" ni?","wrong_answer":"fungana","correct_answer":"fungua"}'::jsonb, 'Funga/fungua and vaa/vua make -ua look like a rule for all verbs.', 'The question "Kauli ya kutendua ya "funga" ni?" with "fungana" among the options.', 'Keep a list of real reversives (funga/fungua, choma/chomoa, ziba/zibua); test new ones in the dictionary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA.M_MUK_MIX', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA', 'Calls formal language informal, or informal language formal.', '{"question":"\"Niaje, msee?\" ni lugha ___.","wrong_answer":"rasmi","correct_answer":"isiyo rasmi"}'::jsonb, 'The child does not look at who is speaking to whom.', 'The question ""Niaje, msee?" ni lugha ___." with "rasmi" among the options.', 'A greeting between friends and a greeting to a leader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA.M_MUK_INFORMAL', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA', 'Uses slang or casual words with a teacher, a leader or at a meeting.', '{"question":"Chagua sentensi inayofaa unapozungumza na mwalimu mkuu.","wrong_answer":"Nipe ruhusa tu.","correct_answer":"Mwalimu mkuu, naomba ruhusa ya kuondoka mapema."}'::jsonb, 'The child uses the way he talks to friends everywhere.', 'The question "Chagua sentensi inayofaa unapozungumza na mwalimu mkuu." with "Nipe ruhusa tu." among the options.', 'A request to a leader with a casual version among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA.M_MUK_FORMAL_FRIEND', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA', 'Uses very formal words with a friend or a sister at home.', '{"question":"Chagua sentensi inayofaa unapozungumza na rafiki uwanjani.","wrong_answer":"Naomba kibali cha kuanza mchezo.","correct_answer":"Twende tucheze mpira, rafiki!"}'::jsonb, 'The child thinks formal words are always better.', 'The question "Chagua sentensi inayofaa unapozungumza na rafiki uwanjani." with "Naomba kibali cha kuanza mchezo." among the options.', 'A friendly invitation next to a formal one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA.M6_MUK_PHONE', 'KISW.G6.KUSIKI.T9_MAZUNGUMZO_YA_KIMUKT.MUKTADHA', 'Speaks on the phone to an official as to a friend (Sema!, Uko wapi?) with no greeting or name.', '{"question":"Unampigia simu mwalimu mkuu. Unaanza vipi?","wrong_answer":"Sema! Uko wapi?","correct_answer":"Hujambo mwalimu mkuu? Ni mimi Amina wa darasa la sita."}'::jsonb, 'Phone talk with friends is the model the child knows.', 'The question "Unampigia simu mwalimu mkuu. Unaanza vipi?" with "Sema! Uko wapi?" among the options.', 'Role-play a phone call: greet, say who you are, say why you call, thank, take leave.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_COVER_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu afya ya akili. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu afya ya akili. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_LEVEL_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Zawadi Azungumza na Mshauri\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Zawadi Azungumza na Mshauri" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_TITLEMSG_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Zawadi Azungumza na Mshauri\" ni upi?","wrong_answer":"Zawadi Azungumza na Mshauri","correct_answer":"Tukizungumza na mtu tunayemwamini, tunapunguza mawazo mazito."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Zawadi Azungumza na Mshauri" ni upi?" with "Zawadi Azungumza na Mshauri" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_DETAIL_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu afya ya akili?","wrong_answer":"Zawadi alikaa chini ya mti peke yake.","correct_answer":"Tukizungumza na mtu tunayemwamini, tunapunguza mawazo mazito."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu afya ya akili?" with "Zawadi alikaa chini ya mti peke yake." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_KIND_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M6_MAP_WORD_T9', 'KISW.G6.KUSOMA.T9_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (msongo).', '{"question":"Katika matini: \"Msongo wa mawazo ulimfanya Zawadi akose usingizi.\" Neno \"msongo\" lina maana gani?","wrong_answer":"msitu mnene","correct_answer":"mawazo mengi yanayomlemea mtu"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Msongo wa mawazo ulimfanya Zawadi akose usingizi." Neno "msongo" lina maana gani?" with "msitu mnene" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STORY_T9', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Jinsi ya Kupunguza Mawazo Mengi\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Kwanza, zungumza na mtu unayemwamini kuhusu jambo linalokusumbua."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Jinsi ya Kupunguza Mawazo Mengi"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_DETAIL_T9', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Jinsi ya Kupunguza Mawazo Mengi\"?","wrong_answer":"Mawazo ni mabaya.","correct_answer":"Kwanza, zungumza na mtu unayemwamini kuhusu jambo linalokusumbua."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Jinsi ya Kupunguza Mawazo Mengi"?" with "Mawazo ni mabaya." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_STEPS_T9', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Jinsi ya Kupunguza Mawazo Mengi\"?","wrong_answer":"omba msaada wa mshauri, lala vya kutosha, cheza au fanya mazoezi, zungumza na mtu","correct_answer":"zungumza na mtu, cheza au fanya mazoezi, lala vya kutosha, omba msaada wa mshauri"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Jinsi ya Kupunguza Mawazo Mengi"?" with "omba msaada wa mshauri, lala vya kutosha, cheza au fanya mazoezi, zungumza na mtu" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_OFFTOPIC_T9', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Jinsi ya Kupunguza Mawazo Mengi\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, zungumza na mtu unayemwamini kuhusu jambo linalokusumbua."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Jinsi ya Kupunguza Mawazo Mengi", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO.M6_INS_PARAS_T9', 'KISW.G6.KUANDI.T9_INSHA_ZA_MAELEZO.INSHA_MAELEZO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Jinsi ya Kupunguza Mawazo Mengi\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Jinsi ya Kupunguza Mawazo Mengi" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI.M_VINY_SAME', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI', 'Repeats the word as its own opposite.', '{"question":"Mfuko huu ni mzito lakini ule ni ___.","wrong_answer":"mzito","correct_answer":"mwepesi"}'::jsonb, 'The child does not read the word lakini that signals a contrast.', 'The question "Mfuko huu ni mzito lakini ule ni ___." with "mzito" among the options.', 'A sentence with lakini and the same word among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI.M_VINY_OTHER', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI', 'Picks a different adjective that is not the opposite (mdogo for mfupi).', '{"question":"Mti huu ni mrefu lakini ule ni ___.","wrong_answer":"mdogo","correct_answer":"mfupi"}'::jsonb, 'The child picks a word from the same field (size) without checking it is the exact opposite.', 'The question "Mti huu ni mrefu lakini ule ni ___." with "mdogo" among the options.', 'A word with a near neighbour of meaning among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI.M_VINY_NO_AGREE', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI', 'Gives the opposite without the prefix of the noun (refu for mrefu, jinga for mjinga).', '{"question":"Kiti hiki ni kigumu lakini kile ni ___.","wrong_answer":"kilaini","correct_answer":"laini"}'::jsonb, 'The child changes the opposite to fit the noun when it does not change, or leaves out the prefix when it must.', 'The question "Kiti hiki ni kigumu lakini kile ni ___." with "kilaini" among the options.', 'Options with and without the prefix.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI.M6_VINY_NEGATE', 'KISW.G6.SARUFI.T9_VINYUME_VYA_VIVUMISH.VINYUME_VIVUMISHI', 'Makes the opposite with si- or "si" (si mrefu for mfupi).', '{"question":"Kinyume cha \"mrefu\" ni?","wrong_answer":"si mrefu","correct_answer":"mfupi"}'::jsonb, 'Negation is a quick way to say "not", so the child uses it as the opposite.', 'The question "Kinyume cha "mrefu" ni?" with "si mrefu" among the options.', 'An opposite is another adjective: mrefu/mfupi, mpana/mwembamba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI.M_SIT_WRONG_ANIMAL', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI', 'Names the wrong animal for the behaviour (kobe for a hard worker).', '{"question":"Kamau hufanya kazi kutwa nzima bila kuchoka. Kamau ni ___.","wrong_answer":"kobe","correct_answer":"nyuki"}'::jsonb, 'The child does not link the animal with the behaviour it stands for.', 'The question "Kamau hufanya kazi kutwa nzima bila kuchoka. Kamau ni ___." with "kobe" among the options.', 'A behaviour with several animals among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI.M_SIT_TASHBIHI', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI', 'Takes a sentence with kama (a tashbihi) for a sitiari.', '{"question":"Chagua sentensi iliyo sitiari.","wrong_answer":"Mwalimu ni kama simba.","correct_answer":"Mwalimu ni simba."}'::jsonb, 'The child does not tell the two figures apart.', 'The question "Chagua sentensi iliyo sitiari." with "Mwalimu ni kama simba." among the options.', 'A sitiari and a tashbihi on the same subject.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI.M_SIT_LITERAL', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI', 'Takes the sitiari word for word (the teacher really has a lion).', '{"question":"Chagua sentensi iliyo sitiari.","wrong_answer":"Mwalimu ana simba.","correct_answer":"Mwalimu ni simba."}'::jsonb, 'The child reads the sentence as a plain statement.', 'The question "Chagua sentensi iliyo sitiari." with "Mwalimu ana simba." among the options.', 'A sitiari beside a sentence with the verb kuwa na.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI.M6_SIT_WRONG_TRAIT', 'KISW.G6.KUSIKI.T10_SITIARI_ZA_TABIA.SITIARI', 'Uses a sitiari whose animal stands for another trait (Amina ni fisi for a kind girl).', '{"question":"Ni sitiari ipi inamfaa mtu mkarimu?","wrong_answer":"Yeye ni fisi.","correct_answer":"Yeye ni njiwa."}'::jsonb, 'The child knows the pattern X ni Y but not what each animal stands for.', 'The question "Ni sitiari ipi inamfaa mtu mkarimu?" with "Yeye ni fisi." among the options.', 'Use the folk-tale chart: fisi - ulafi, sungura - ujanja, njiwa - upole, simba - ushujaa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_FOLDER_T10', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Mixes up a folder and a file: looks for the passage on the screen without opening the folder it is in.', '{"question":"Kifungu \"Usalama wa Jamii\" kimehifadhiwa ndani ya folda \"Kiswahili\". Utakifunguaje?","wrong_answer":"bonyeza \"Usalama wa Jamii\" kwenye skrini ya mwanzo","correct_answer":"fungua folda \"Kiswahili\", kisha bonyeza mara mbili faili \"Usalama wa Jamii\""}'::jsonb, 'The child has only used apps on a phone, where there are no folders.', 'The question "Kifungu "Usalama wa Jamii" kimehifadhiwa ndani ya folda "Kiswahili". Utakifunguaje?" with "bonyeza "Usalama wa Jamii" kwenye skrini ya mwanzo" among the options.', 'Show a real folder (a box file) holding papers; then the same on the screen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_SEARCH_T10', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Types a whole long question, with spelling mistakes, into the search box.', '{"question":"Unatafuta habari kuhusu kukabiliana na ugaidi. Utaandika nini kwenye kisanduku cha kutafutia?","wrong_answer":"naomba unipe habari zote kuhusu kukabiliana na ugaidi tafadhali","correct_answer":"usalama jamii ugaidi watoto"}'::jsonb, 'The child talks to the search box as to a person.', 'The question "Unatafuta habari kuhusu kukabiliana na ugaidi. Utaandika nini kwenye kisanduku cha kutafutia?" with "naomba unipe habari zote kuhusu kukabiliana na ugaidi tafadhali" among the options.', 'Underline the two or three words that carry the meaning; search with those; compare the results.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_POPUP_T10', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Clicks a pop-up or an advert that says he has won a prize.', '{"question":"Ukiwa unasoma, ujumbe unatokea: \"Umeshinda simu! Bonyeza hapa.\" Ufanye nini?","wrong_answer":"bonyeza ili kupokea simu","correct_answer":"usibonyeze; funga ujumbe na umwambie mwalimu au mzazi"}'::jsonb, 'Offers of prizes are exciting and the child does not know they are traps.', 'The question "Ukiwa unasoma, ujumbe unatokea: "Umeshinda simu! Bonyeza hapa." Ufanye nini?" with "bonyeza ili kupokea simu" among the options.', 'Show two screenshots, one real page and one trap; the child finds three signs of the trap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_SITE_T10', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Uses any site that comes up and gives his name, school or phone number when a site asks.', '{"question":"Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?","wrong_answer":"jaza ili usome hadithi","correct_answer":"usijaze; tumia tovuti salama aliyokupa mwalimu"}'::jsonb, 'The child wants the story and does not see personal details as worth protecting.', 'The question "Tovuti inakuuliza jina lako kamili, shule yako na nambari ya simu ya mzazi kabla ya kusoma hadithi. Ufanye nini?" with "jaza ili usome hadithi" among the options.', 'List the details that are private; practise saying no to a form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI.M6_KID_ORDER_T10', 'KISW.G6.KUSOMA.T10_KUSOMA_KWA_MAPANA.KUSOMA_KIDIJITALI', 'Puts the steps of finding and reading a passage in the wrong order (reads before searching, or searches before switching on).', '{"question":"Ni hatua ipi huja kwanza?","wrong_answer":"andika maneno ya kutafutia","correct_answer":"washa tarakilishi na ufungue kivinjari"}'::jsonb, 'The child has watched an adult do the steps quickly and remembers the parts, not the order.', 'The question "Ni hatua ipi huja kwanza?" with "andika maneno ya kutafutia" among the options.', 'Step cards: the child orders them, then does them on a real device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_FACTS_T10', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Writes facts or an explanation where a story of events is asked.', '{"question":"Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani \"Mfuko Uliotiliwa Shaka\"?","wrong_answer":"Ugaidi ni tishio kwa usalama wa nchi.","correct_answer":"Mlinzi aliona mfuko mweusi ukiwa peke yake kituoni."}'::jsonb, 'The child knows a lot about the topic and writes what he knows instead of telling what happened.', 'The question "Ni sentensi ipi ni mwanzo wa insha ya masimulizi yenye anwani "Mfuko Uliotiliwa Shaka"?" with "Ugaidi ni tishio kwa usalama wa nchi." among the options.', 'Ask: who, where, what happened first, then, in the end? A story answers these; an explanation does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_TENSE_T10', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Tells a past story in the present tense (-na-), or mixes -na- and -li- in one story.', '{"question":"Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: \"Mfuko Uliotiliwa Shaka\"?","wrong_answer":"Mlinzi anaona mfuko mweusi ukiwa peke yake kituoni.","correct_answer":"Mlinzi aliona mfuko mweusi ukiwa peke yake kituoni."}'::jsonb, 'The child writes as he speaks while remembering, and English stories in class are told in the present too.', 'The question "Ni sentensi ipi inafaa katika masimulizi ya jambo lililotokea jana: "Mfuko Uliotiliwa Shaka"?" with "Mlinzi anaona mfuko mweusi ukiwa peke yake kituoni." among the options.', 'Circle every verb; check its tense marker against the time words (jana, siku moja).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_ORDER_T10', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Mfuko Uliotiliwa Shaka\"?","wrong_answer":"mfuko ulikaguliwa, polisi walifika, aliwaonya watu, mlinzi aliona mfuko","correct_answer":"mlinzi aliona mfuko, aliwaonya watu, polisi walifika, mfuko ulikaguliwa"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Mfuko Uliotiliwa Shaka"?" with "mfuko ulikaguliwa, polisi walifika, aliwaonya watu, mlinzi aliona mfuko" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_END_T10', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Mfuko Uliotiliwa Shaka\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza kuwa mwangalifu kila wakati."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Mfuko Uliotiliwa Shaka"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI.M6_INS_OFFTOPIC_T10', 'KISW.G6.KUANDI.T10_INSHA_ZA_MASIMULIZI.INSHA_MASIMULIZI', 'Puts in points that are not about the title.', '{"question":"Katika insha ya masimulizi yenye anwani \"Mfuko Uliotiliwa Shaka\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Mlinzi aliona mfuko mweusi ukiwa peke yake kituoni."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya masimulizi yenye anwani "Mfuko Uliotiliwa Shaka", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI.M_MASH_TENSE', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI', 'Uses a tense marker (-li-, -na-, -ta-) where a condition marker (-ki-, -nge-) is needed.', '{"question":"___ kwa bidii, utafaulu mtihani.","wrong_answer":"Ulisoma","correct_answer":"Ukisoma"}'::jsonb, 'The child knows tenses and not the condition marker.', 'The question "___ kwa bidii, utafaulu mtihani." with "Ulisoma" among the options.', 'A sentence with if in the meaning and tense forms among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI.M_MASH_NEG', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI', 'Uses -sipo- (do not) where the condition is to do (-ki-).', '{"question":"Wanafunzi ___ pamoja, watamaliza kazi haraka.","wrong_answer":"wasipofanya","correct_answer":"wakifanya"}'::jsonb, 'The child does not read the whole sentence for meaning.', 'The question "Wanafunzi ___ pamoja, watamaliza kazi haraka." with "wasipofanya" among the options.', 'A condition whose result only makes sense if it is positive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI.M_MASH_ID_TENSE', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI', 'Names the tense marker (-ta-) as the condition marker.', '{"question":"Ni kiambishi kipi cha masharti katika \"Ukisoma, utafaulu\"?","wrong_answer":"-ta-","correct_answer":"-ki-"}'::jsonb, 'The child finds a marker in the verb but picks the wrong one.', 'The question "Ni kiambishi kipi cha masharti katika "Ukisoma, utafaulu"?" with "-ta-" among the options.', 'A sentence with both -ki- and -ta- and both in the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI.M_MASH_ID_PERSON', 'KISW.G6.SARUFI.T10_HALI_YA_MASHARTI_NGE.MASHARTI', 'Names the person prefix (u-, a-, ni-) as the condition marker.', '{"question":"Ni kiambishi kipi cha masharti katika \"Angekuja, angeona\"?","wrong_answer":"-a-","correct_answer":"-nge-"}'::jsonb, 'The child picks the first marker in the verb.', 'The question "Ni kiambishi kipi cha masharti katika "Angekuja, angeona"?" with "-a-" among the options.', 'A verb with a person prefix and a condition marker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA.M6_MSM_DETAIL_T11', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'Gives a detail of the narration as its message.', '{"question":"Ulisikiliza masimulizi kuhusu wanakijiji waliojenga barabara kwa pesa za ushuru. Ujumbe wake ni upi?","wrong_answer":"Barabara mpya ilikuwa ya lami.","correct_answer":"Tukilipa ushuru, serikali hutujengea huduma kama barabara na shule."}'::jsonb, 'The detail was vivid; the child has not asked what the whole narration teaches.', 'The question "Ulisikiliza masimulizi kuhusu wanakijiji waliojenga barabara kwa pesa za ushuru. Ujumbe wake ni upi?" with "Barabara mpya ilikuwa ya lami." among the options.', 'After listening, ask: what did the speaker want us to learn? Then: what is one thing that happened?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA.M6_MSM_ORDER_T11', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'Retells the events in a mixed order, starting with the most exciting part.', '{"question":"Unaposimulia, unaanza na nini?","wrong_answer":"sehemu ya kusisimua zaidi","correct_answer":"mwanzo: nani, wapi, lini"}'::jsonb, 'The child jumps to the part that impressed him most.', 'The question "Unaposimulia, unaanza na nini?" with "sehemu ya kusisimua zaidi" among the options.', 'Retell with three fingers: mwanzo, kati, mwisho.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA.M6_MSM_GESTURE_T11', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'Uses gestures or a face that do not match the words (smiles while telling a sad part, stands still for an action).', '{"question":"Unasimulia: \"Tuliiona barabara ndefu ikinyooka hadi mjini!\" Ishara ipi inafaa?","wrong_answer":"kukunja mikono kifuani","correct_answer":"kunyoosha mkono mbele kuonyesha urefu"}'::jsonb, 'The child is nervous and does not link the body to the words.', 'The question "Unasimulia: "Tuliiona barabara ndefu ikinyooka hadi mjini!" Ishara ipi inafaa?" with "kukunja mikono kifuani" among the options.', 'Mirror game in pairs: one says a line, the other shows the feeling; swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA.M6_MSM_MIX_T11', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'Mixes English or Sheng into the telling (Then tukaenda..., ilikuwa poa sana).', '{"question":"Ni sentensi ipi inafaa unaposimulia darasani?","wrong_answer":"Then tukaenda home, ilikuwa poa sana.","correct_answer":"Kisha tukaenda nyumbani; ilikuwa siku nzuri sana."}'::jsonb, 'The child narrates as he talks with friends.', 'The question "Ni sentensi ipi inafaa unaposimulia darasani?" with "Then tukaenda home, ilikuwa poa sana." among the options.', 'Record a telling; play it back; the child finds the non-Kiswahili words and replaces them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA.M6_MSM_OFFTOPIC_T11', 'KISW.G6.KUSIKI.T11_KUJIELEZA_KWA_UFASAH.KUJIELEZA', 'Tells a story that is not on the topic given (ushuru (taxes)).', '{"question":"Mada ni ushuru (taxes). Ni masimulizi yapi yanafaa?","wrong_answer":"Siku nilipotazama mechi ya mpira","correct_answer":"Siku wanakijiji waliojenga barabara kwa pesa za ushuru"}'::jsonb, 'The child tells the story he knows best, whatever the topic.', 'The question "Mada ni ushuru (taxes). Ni masimulizi yapi yanafaa?" with "Siku nilipotazama mechi ya mpira" among the options.', 'Write the topic on the board; before telling, the child says in one sentence how his story fits it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_WORDBYWORD_T11', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Serikali hutumia ushuru kujenga hospitali, shule na barabara.\"?","wrong_answer":"Serikali ... hutumia ... ushuru ... kujenga ... hospitali, ... shule ... na ... barabara.","correct_answer":"Serikali hutumia ushuru kujenga hospitali, shule na barabara."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Serikali hutumia ushuru kujenga hospitali, shule na barabara."?" with "Serikali ... hutumia ... ushuru ... kujenga ... hospitali, ... shule ... na ... barabara." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_RACE_T11', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_FLAT_T11', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, unajua ushuru hulipwa wapi?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, unajua ushuru hulipwa wapi?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_NOPAUSE_T11', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Hongera, umelipa ushuru kwa wakati!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Hongera, umelipa ushuru kwa wakati!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M6_UFS_SOUND_T11', 'KISW.G6.KUSOMA.T11_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (serikali read as selikali).', '{"question":"Neno \"serikali\" linatamkwa vipi?","wrong_answer":"selikali","correct_answer":"serikali"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "serikali" linatamkwa vipi?" with "selikali" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_ONEADDR_T11', 'KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Writes only one address, or puts the receiver''s address at the top right.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja, ya mwandishi","correct_answer":"mbili: ya mwandishi (kulia juu) na ya mpokeaji (kushoto)"}'::jsonb, 'The friendly letter has one address and the child carries it over.', 'The question "Barua rasmi ina anwani ngapi?" with "moja, ya mwandishi" among the options.', 'Label both addresses on a model; the child writes his own and the receiver''s on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_NOREF_T11', 'KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Leaves out the subject line (KUH: or YAH:) or writes it as a long sentence.', '{"question":"Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kuelimishwa kuhusu ushuru?","wrong_answer":"Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi.","correct_answer":"KUH: OMBI LA KUELIMISHWA KUHUSU USHURU"}'::jsonb, 'The child does not know the reader of an official letter needs the subject before reading.', 'The question "Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la kuelimishwa kuhusu ushuru?" with "Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi." among the options.', 'Underline the KUH: line on three real letters; it is short and in capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_CASUAL_T11', 'KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Uses friendly words in an official letter (Mpendwa rafiki, Hujambo?, Wako akupendaye).', '{"question":"Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?","wrong_answer":"Hujambo mwalimu wangu mpendwa!","correct_answer":"Kwa Mwalimu Mkuu,"}'::jsonb, 'The friendly letter is the first letter learnt and its words come first.', 'The question "Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?" with "Hujambo mwalimu wangu mpendwa!" among the options.', 'Sort salamu and closing cards into "kirafiki" and "rasmi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI.M6_INS_SIGNOFF_T11', 'KISW.G6.KUANDI.T11_BARUA_RASMI.KUANDIKA_BARUA_RASMI', 'Ends with only a first name and no signature, or with "Ni mimi rafiki yako".', '{"question":"Barua rasmi humalizika vipi?","wrong_answer":"Ni mimi rafiki yako, Wanjiku","correct_answer":"Wako mtiifu, sahihi, na jina kamili: Wanjiku Kamau"}'::jsonb, 'The friendly closing is a habit.', 'The question "Barua rasmi humalizika vipi?" with "Ni mimi rafiki yako, Wanjiku" among the options.', 'Model the closing block (Wako mtiifu, sahihi, jina kamili) and have the child copy it once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI.M_UKM_SI_ONLY', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI', 'Only puts si- in front and keeps -ki- (Usikisoma for Usiposoma).', '{"question":"Neno \"Ukisoma\" likikanushwa huwa ___.","wrong_answer":"Usikisoma","correct_answer":"Usiposoma"}'::jsonb, 'The child applies the rule for negating a command or a tense to the conditional.', 'The question "Neno "Ukisoma" likikanushwa huwa ___." with "Usikisoma" among the options.', 'A conditional verb with the si-form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI.M_UKM_KEEP_KI', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI', 'Negates with ha- and keeps -ki- (Hukisoma, Hakija).', '{"question":"Neno \"Akija\" likikanushwa huwa ___.","wrong_answer":"Hakija","correct_answer":"Asipokuja"}'::jsonb, 'The child applies the rule for negating a tense to the conditional.', 'The question "Neno "Akija" likikanushwa huwa ___." with "Hakija" among the options.', 'A conditional verb with the ha-form among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI.M_UKM_COMMAND', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI', 'Gives the negative command (Usisome, Asije) for the negative condition.', '{"question":"Neno \"Ukisoma\" likikanushwa huwa ___.","wrong_answer":"Usisome","correct_answer":"Usiposoma"}'::jsonb, 'The child knows the negative command and uses it for every negative.', 'The question "Neno "Ukisoma" likikanushwa huwa ___." with "Usisome" among the options.', 'A conditional verb with the negative command among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI.M6_UKM_NGE_NEG', 'KISW.G6.SARUFI.T11_UKANUSHAJI_WA_MANENO.UKANUSHAJI_MASHARTI', 'Negates -nge- with ha- and keeps it whole (hangekuja) instead of the si- form (asingekuja).', '{"question":"Kanusha: Angekuja, tungefurahi.","wrong_answer":"Hangekuja, hatungefurahi.","correct_answer":"Asingekuja, tusingefurahi."}'::jsonb, 'Ha- is the negative the child knows best.', 'The question "Kanusha: Angekuja, tungefurahi." with "Hangekuja, hatungefurahi." among the options.', 'Show the pattern: -nge- negates with -singe-: asingekuja, tusingefurahi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI.M_UKUB_SWAP', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI', 'Swaps the big form (ji-) and the small form (kiji-).', '{"question":"Kitabu kikubwa sana huitwa ___.","wrong_answer":"kijitabu","correct_answer":"jitabu"}'::jsonb, 'The child learned both forms but not which is for big and which for small.', 'The question "Kitabu kikubwa sana huitwa ___." with "kijitabu" among the options.', 'A big or small noun with both forms among the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI.M_UKUB_PLURAL', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI', 'Gives the plain plural (vitabu) where the big or small form is asked.', '{"question":"Kitabu kikubwa sana huitwa ___.","wrong_answer":"vitabu","correct_answer":"jitabu"}'::jsonb, 'The child confuses a big thing with many things.', 'The question "Kitabu kikubwa sana huitwa ___." with "vitabu" among the options.', 'Options with the plain plural.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI.M_UKUB_NO_CHANGE', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI', 'Leaves the noun unchanged (kitabu for jitabu or kijitabu).', '{"question":"Kisu kidogo huitwa ___.","wrong_answer":"kisu","correct_answer":"kijisu"}'::jsonb, 'The child does not see that size changes the noun.', 'The question "Kisu kidogo huitwa ___." with "kisu" among the options.', 'Options with the plain noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI.M_UKUB_SINGULAR', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N.UKUBWA_KI', 'Gives the singular where the plural is asked.', '{"question":"Wingi wa \"jitabu\" ni ___.","wrong_answer":"jitabu","correct_answer":"majitabu"}'::jsonb, 'The child does not read the word wingi.', 'The question "Wingi wa "jitabu" ni ___." with "jitabu" among the options.', 'Options with the singular.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI.M6_UKJ_DROP_JI', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI', 'Drops the ji- of the noun before adding the small prefix (kiwe for kijiwe).', '{"question":"Udogo wa \"jiwe\" ni?","wrong_answer":"kiwe","correct_answer":"kijiwe"}'::jsonb, 'For m- and ki- nouns the old prefix is dropped first, and the child does the same with ji-, which here is part of the stem.', 'The question "Udogo wa "jiwe" ni?" with "kiwe" among the options.', 'Show that jiwe has no plain root -we that is used alone; keep jiwe whole and add ki-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI.M6_UKJ_SAME_BIG', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI', 'Thinks a ji- noun is already in the big form and leaves it unchanged (jiwe for jijiwe).', '{"question":"Ukubwa wa \"jicho\" ni?","wrong_answer":"jicho","correct_answer":"jijicho"}'::jsonb, 'ji- is the big prefix the child learnt, so a noun that starts with it looks big already.', 'The question "Ukubwa wa "jicho" ni?" with "jicho" among the options.', 'Compare jiwe (an ordinary stone) and jitu (a giant from mtu); the first ji- is part of the noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI.M6_UKJ_AGREE', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI', 'Gives the small form but keeps the LI-YA agreement (kijiwe limeanguka for kijiwe kimeanguka).', '{"question":"Jaza: Kijiwe ___ (kimeanguka / limeanguka).","wrong_answer":"limeanguka","correct_answer":"kimeanguka"}'::jsonb, 'The child changes the noun and keeps the agreement of jiwe.', 'The question "Jaza: Kijiwe ___ (kimeanguka / limeanguka)." with "limeanguka" among the options.', 'The small form moves to KI-VI: kijiwe kimeanguka, vijiwe vimeanguka.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI.M6_UKJ_PLURAL', 'KISW.G6.SARUFI.T11_UKUBWA_NA_UDOGO_WA_N_2.UKUBWA_JI', 'Makes the plural of the small form with ma- (makijiwe) or of the big form with vi- (vijijiwe).', '{"question":"Wingi wa \"kijiwe\" ni?","wrong_answer":"makijiwe","correct_answer":"vijiwe"}'::jsonb, 'The child adds the plural prefix of the ordinary noun (mawe) to the new form.', 'The question "Wingi wa "kijiwe" ni?" with "makijiwe" among the options.', 'Small forms take vi- in the plural (vijiwe); big forms take ma- (majijiwe).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
